window.WARMUP_BANK=[{"id":"warm-soc-01","field":"社会科学","question":"同样一份保险定价方案，高低收入者的公平感可能不同。研究特别发现哪种心理差异？","options":["他们可能更习惯体谅交易的不同一方","他们可能对风险高低掌握了不同资料","他们可能使用了不同的折扣作参照","他们可能对保险合同期限理解不同"],"answer":0,"explanation":"公平感也会跟着我们站在哪一边而变化。三轮问卷中，高收入者更常认可风险定价，也更能体谅公司；这种差异不只是个人利益不同。不过，问卷关联不等于收入提高就必然改变立场。","bridge":"把价格争论拆成两个人的处境，就接上了选择性共情研究。","paperId":"social-soc-top-1","tryThis":"用两句话分别替保险公司和高风险客户说说，他们最担心什么。","keywords":["公平感","定价","共情"],"paper":{"id":"social-soc-top-1","title":"Seeing Like a Company or a Customer: Selective Empathy in Pricing","venue":"American Sociological Review","year":2025,"url":"https://doi.org/10.1177/00031224251394724","doi":"10.1177/00031224251394724","summary":["保险或贷款给高风险客户开更高价格，为什么有些人觉得公平，有些人却反感？","研究通过三轮问卷，比较不同收入者怎样评价风险定价，又更能理解交易中的哪一方。","高收入者更常认可风险定价，也更愿意体谅公司而非高风险客户，这种差异不只是自身利益造成的。"],"methods":["问卷调查","群体比较"]}},{"id":"warm-soc-02","field":"社会科学","question":"两位篮球运动员表现接近，其中一人进过 NBA 全明星。研究发现，旧头衔可能怎样影响下一次评选？","options":["旧头衔会让评选更倾向推荐新人","旧头衔还会带来额外的入选优势","旧头衔的影响只体现在球衣销量","旧头衔只通过当季表现间接起作用"],"answer":1,"explanation":"名气也会继续生出名气。研究把球员表现与历年评选记录放在一起，发现再次入选的优势，一部分来自表现进步，一部分来自评选对已有地位的偏向；多次入选还能累积优势。这不是说所有入选都只靠头衔。","bridge":"从一个全明星头衔出发，可以研究成功怎样帮助自己继续成功。","paperId":"exp2200-soc-top-026","tryThis":"想一个你喜欢的获奖作品，分别写下你喜欢的一个细节和它获得的一个标签。","keywords":["NBA","名气","累积优势"],"paper":{"id":"exp2200-soc-top-026","title":"They Can’t All Be Stars: The Matthew Effect, Cumulative Status Bias, and Status Persistence in NBA All-Star Elections","venue":"American Sociological Review","year":2023,"url":"https://doi.org/10.1177/00031224231159139","doi":"10.1177/00031224231159139","summary":["进过一次NBA全明星，下一次入选是不是更容易？","研究利用历年球员表现和全明星评选记录，尽量分开实际表现提升与既有名气带来的优势。","过去入选确实提高再次入选的机会，一部分来自表现进步，一部分则是评选偏向已有地位，多次入选还会继续累积优势。"],"methods":["长期记录分析","马太效应检验"]}},{"id":"warm-soc-03","field":"社会科学","question":"你刚说“随便”，发现朋友正要把你不吃的菜点上。哪句话在提前修补误会？","options":["你确定这家店的香菜是另放的吗","那你再问问其他人想吃哪一道","我说随便，是指除了香菜都可以","这次你来点，下次我再决定菜单"],"answer":2,"explanation":"说话不只是把句子讲完，也包括盯着对方可能怎样理解。研究分析真实对话，发现人们会赶在误解引发行动前，补充“不是这个意思”或明确应有理解。补这一句，本身就是对话组织的一部分。","bridge":"一句日常补充说明，能成为研究对话怎样避免走偏的材料。","paperId":"social-soc-top-15","tryThis":"把“有空聊聊”改成一句不容易被误解的邀请，补上时间或主题。","keywords":["对话","误解","日常互动"],"paper":{"id":"social-soc-top-15","title":"Pre-emptive Repair of Potential Misunderstandings: Prospective Procedures for Managing Intersubjectivity and Steering Social Action","venue":"American Sociological Review","year":2025,"url":"https://doi.org/10.1177/00031224251347285","doi":"10.1177/00031224251347285","summary":["一句话可能被误解时，人们怎样赶在对方采取行动前把意思说清？","研究分析多个社会场景的真实对话，专门观察说话者提前补充解释的时机和方式。","人们会先说明自己不是某个意思，或补上应有理解，以免对方沿着误会继续行动。"],"methods":["真实对话分析","会话分析"]}},{"id":"warm-soc-04","field":"社会科学","question":"一个班跨群体友谊不少，却全靠两位“社交达人”连接。这样就能说明全班融合了吗？","options":["能，只要跨群体朋友总数够多","能，两个群体都会自动互相熟悉","能，认识达人等于认识全部朋友","未必，还要看联系是否只集中在少数人"],"answer":3,"explanation":"桥很多和人人都过桥，是两回事。班级友谊网络研究发现，跨群体联系越集中在少数学生身上，本地学生越容易排斥移民。即使控制个人朋友数和全班跨群体联系，这种关联仍存在。","bridge":"从数朋友到画出谁连接谁，你已经碰到了社会网络分析。","paperId":"social-soc-top-21","tryThis":"画六个圆点代表小组成员，连起熟悉彼此的人，看看谁是唯一的桥。","keywords":["友谊网络","群体融合","关系分布"],"paper":{"id":"social-soc-top-21","title":"Uneven Mixing, Network Segregation, and Immigrant Integration","venue":"American Sociological Review","year":2025,"url":"https://doi.org/10.1177/00031224251336471","doi":"10.1177/00031224251336471","summary":["移民与本地人之间有朋友来往，为什么仍可能谈不上真正融合？","研究分析班级友谊网络，区分跨群体友谊是广泛分布，还是集中在少数学生身上。","联系越集中在少数人身上，本地学生越容易排斥移民，即使控制个人朋友数量和全班跨群体联系仍如此。"],"methods":["社会网络分析","态度比较"]}},{"id":"warm-soc-05","field":"社会科学","question":"有人去健身房，不只是为了练肌肉，还会惦记一起训练的朋友。英国 CrossFit 访谈研究看到什么？","options":["训练也能带来像临时小社区一样的归属","友谊主要形成在竞争最激烈的时刻","归属主要来自不与其他会员打交道","参加后个人身体目标会逐渐消失"],"answer":0,"explanation":"一起流汗，也可能是在一起找归属。作者访谈英国四家健身房的十八名参与者，发现训练、友谊与个人成长交织成社区般的亲密感。不过，这些关系也依附于消费和持续参与，退出后可能松动，结论来自小范围访谈。","bridge":"一次共同训练里的陪伴感，能接到消费空间怎样形成社区的研究。","paperId":"exp2200-soc-reg-010","tryThis":"想一个你常参加的活动，写下让你想再去的一件事和一个人。","keywords":["健身","归属感","临时社区"],"paper":{"id":"exp2200-soc-reg-010","title":"CrossFit, Community, and Identity: A Gemeinschaft in a Liquid Modern World?","venue":"Sociological Research Online","year":2024,"url":"https://doi.org/10.1177/13607804241258626","doi":"10.1177/13607804241258626","summary":["CrossFit健身房里的亲密感，为什么像一个临时的小社区？","研究访谈英国四家健身房的18名参与者，用“流动现代性”理论分析友谊、身体训练与个人成长之间的关系。","健身房能提供陪伴和归属，但这些关系依附于消费与自我提升，也可能随参与结束而松动。"],"methods":["半结构访谈","社会理论分析"]}},{"id":"warm-soc-06","field":"社会科学","question":"最亲的朋友也有你暂时不想聊的话题。这就说明你不信任这个人吗？","options":["亲密程度越高，就越适合谈所有话题","未必，倾诉取决于对象与话题的搭配","主要取决于这个人的朋友总数多少","相同话题面对所有朋友都会一样难聊"],"answer":1,"explanation":"一个人可以是旅行上的好伙伴，却未必是聊家庭矛盾的合适对象。美国代表性调查把具体亲友和具体难题配对，发现回避与倾诉都很常见。选择不聊，并不能简单归为某个人始终不可信。","bridge":"把“信不信任”换成“这件事找谁聊”，就换了一个研究单位。","paperId":"social-soc-top-53","tryThis":"想一个轻松话题和一个难题，各写下一位你愿意找的人。","keywords":["倾诉","亲密关系","社会支持"],"paper":{"id":"social-soc-top-53","title":"The Avoidance of Strong Ties","venue":"American Sociological Review","year":2024,"url":"https://doi.org/10.1177/00031224241263602","doi":"10.1177/00031224241263602","summary":["面对私人难题时，亲密朋友和家人真的总是最愿意倾诉的对象吗？","研究用新的美国全国代表性调查，把具体问题与具体亲友组合起来考察。","避开亲友与找他们谈话同样常见，是否回避取决于对象和话题的搭配，而非某个人始终不可信。"],"methods":["代表性调查","关系与话题组合分析"]}},{"id":"warm-psy-01","field":"心理学","question":"一首歌的音符都没少，只把前后顺序打乱。没学过音乐的人会受影响吗？","options":["不会，普通听众主要依赖单个音符","会，但额外影响只出现在音量变化时","会，普通听众也会利用较长旋律语境","不会，顺序影响需要经过专门训练"],"answer":2,"explanation":"听歌时，大脑不只是逐个收集音符，还会借前面的旋律理解后面。打乱不同时间尺度音乐的实验中，普通与专业听众都受益于完整调性语境；专业训练的额外优势更多体现在较长乐句结构上。","bridge":"你对旋律“顺不顺”的直觉，能接到音乐预测与记忆的实验。","paperId":"social-psy-top-1","tryThis":"哼一句熟悉的歌，在最后一个音前停住，感受你已经预期到了什么。","keywords":["音乐","预测","记忆"],"paper":{"id":"social-psy-top-1","title":"Listeners Systematically Integrate Hierarchical Tonal Context, Regardless of Musical Training","venue":"Psychological Science","year":2025,"url":"https://doi.org/10.1177/09567976251400331","doi":"10.1177/09567976251400331","summary":["听音乐时，即使没受过专业训练，也会利用前面很长一段旋律来记忆和预测吗？","研究按不同时间尺度打乱真实音乐，比较专业与普通听众的记忆、预测和乐句分段。","两类人都从完整调性语境中受益，训练对基本整合的作用较小，但专业者更敏感于较长乐句结构。"],"methods":["音乐语境操纵","记忆与预测实验"]}},{"id":"warm-psy-02","field":"心理学","question":"盯着一个正在变亮的色块，画面突然消失。记忆可能朝哪个方向偏一点？","options":["可能记得比最后一帧更暗一点","通常正好停在实际的最后一帧","亮度变化越快，记忆越不受影响","可能记得比实际最后一帧更亮一点"],"answer":3,"explanation":"记忆有时像偷偷多走了半步，把变化往后延伸。七项实验发现，亮度、饱和度和形状比例的变化都可能让记忆向未来偏移；色相却没有同样结果。所以这不是所有视觉变化都通用的规律。","bridge":"从记错一个色块，可以追问记忆是不是也在自动预测未来。","paperId":"social-psy-top-4","tryThis":"用手比出一个逐渐变大的圆，突然停住，留意自己还想继续扩大的感觉。","keywords":["视觉记忆","预测","变化"],"paper":{"id":"social-psy-top-4","title":"Representational Momentum Transcends Motion","venue":"Psychological Science","year":2025,"url":"https://doi.org/10.1177/09567976251395074","doi":"10.1177/09567976251395074","summary":["记忆会把一个正在变化的东西，自动记成稍后才会出现的样子吗？","七项实验把常见的运动位置变化，扩展到亮度、颜色饱和度和形状比例的变化。","这些没有位移的变化也让记忆向未来偏移，但色相没有同样现象，显示自动预测有范围限制。"],"methods":["表征动量实验","视觉变化比较"]}},{"id":"warm-psy-03","field":"心理学","question":"摆桌上物品时，“左右按我的身体、前后按房间”这种混用坐标可能吗？","options":["可能，同一个动作能混合两套参照","不可能，一次动作只能用同一套参照","只有先学过测绘，才可能这样混用","房间参照只适用于描述，不用于动作"],"answer":0,"explanation":"空间判断不必整套打包选。让齐马内人与美国参与者摆放物件的实验发现，同一个动作可以在不同轴向上混用身体与环境参照。这种现象跨文化出现，但不能据此说每个人每次都会采用同一组合。","bridge":"一次摆物件的小动作，也能检验我们怎样同时使用多个坐标系。","paperId":"social-psy-top-7","tryThis":"把杯子放在自己的左边，再转身，分别用“我的左边”和“窗边”描述它。","keywords":["空间认知","参照系","身体"],"paper":{"id":"social-psy-top-7","title":"One Action, Two Reference Frames: Compound Cognitive Maps of Object Location","venue":"Psychological Science","year":2025,"url":"https://doi.org/10.1177/09567976251391172","doi":"10.1177/09567976251391172","summary":["摆放一个东西时，人会同时按房间方向和自己身体方向决定它的位置吗？","研究让齐马内人与美国参与者在二维阵列放物件，观察左右和前后各采用什么参照。","同一个动作可以同时使用环境与身体两套坐标，这种混合方式跨文化出现，而非只能一次选一套。"],"methods":["空间放置任务","跨文化比较"]}},{"id":"warm-psy-04","field":"心理学","question":"棋手有公开积分、还有多年比赛反馈，应该就不会高估自己了吧？","options":["有公开分数时，高估通常会完全消失","未必，平均自评仍可能高于实际记录","多数棋手反而会持续低估自己的积分","只有没参加过正式比赛的人才会高估"],"answer":1,"explanation":"有反馈，不代表一定会照单全收。两项预注册研究调查二十二国的有正式积分棋手，并核对后续积分，平均自评仍偏高；低分棋手高估更多，顶尖棋手较准确。这个平均趋势不能替每位棋手下判断。","bridge":"连积分明确的比赛也会出现偏差，让过度自信有了可核查的标尺。","paperId":"social-psy-top-16","tryThis":"在下一次答题前先猜自己能对几题，答完再把预测和实际并排写下。","keywords":["过度自信","反馈","自我评价"],"paper":{"id":"social-psy-top-16","title":"Overconfidence Persists Despite Years of Accurate, Precise, Public, and Continuous Feedback: Two Studies of Tournament Chess Players","venue":"Psychological Science","year":2025,"url":"https://doi.org/10.1177/09567976251360747","doi":"10.1177/09567976251360747","summary":["国际象棋有公开精确的积分和多年比赛反馈，棋手还会长期高估自己吗？","两项预注册研究调查22国3388名有正式积分的棋手，并检查一年后的实际积分。","平均自评仍高于记录，低分棋手高估更多、顶尖棋手较准确，长期客观反馈并未消除过度自信。"],"methods":["预注册调查实验","后续积分检验"]}},{"id":"warm-psy-05","field":"心理学","question":"想把散步坚持下去，除了盯着步数目标，哪种理由在相关研究中更能预测坚持？","options":["把未来达到的步数目标想得更清楚","把运动后得到的外部奖励想得更具体","散步的过程本身让自己享受","更重视别人如何评价自己的运动习惯"],"answer":2,"explanation":"远处的奖励能吸引人出发，过程里的乐趣也能让人愿意再来。中美追踪资料和实际步数研究中，享受过程比外在目标更能预测坚持；增加内在动机的干预也提高遵守程度，但不意味着目标本身没有作用。","bridge":"从“怎样让第一步好玩一点”，能接到持续行动的动机研究。","paperId":"social-psy-top-21","tryThis":"从待学内容里挑一个你真想知道答案的小问题，只读到能回答它为止。","keywords":["内在动机","坚持","学习启动"],"paper":{"id":"social-psy-top-21","title":"Adherence to Personal Resolutions Across Time, Culture, and Goal Domains","venue":"Psychological Science","year":2025,"url":"https://doi.org/10.1177/09567976251350960","doi":"10.1177/09567976251350960","summary":["坚持一年目标，主要靠将来得到的回报，还是行动过程本身就让人愿意继续？","研究结合中美纵向调查、实际步数记录与动机干预，比较内在和外在理由。","享受过程比外在目标更能预测坚持，实验中增加内在动机也提高遵守程度，而非只改变自我报告。"],"methods":["纵向研究","客观行为记录","动机实验"]}},{"id":"warm-psy-06","field":"心理学","question":"有研究想从动画剧本的语法里找性别偏差，除了数角色，特别看了什么？","options":["每集里男性和女性各说多少句话","角色各自的职业和家庭关系如何","男女角色在画面中央出现的时长","句子里谁在做动作，谁在被动承受"],"answer":3,"explanation":"偏差也可能藏在语法里。研究分析约六千六百集美国儿童节目剧本，发现男性更常处在动作发出者的位置，这种句法偏差长期稳定。它不同于单纯的出场人数，也不直接证明观众会受到多大影响。","bridge":"把主语和动作圈出来，一份普通剧本就变成了可分析的数据。","paperId":"social-psy-top-26","tryThis":"找一段故事的三个句子，圈出做动作的人，再看看谁一直没有行动。","keywords":["语言","性别","内容分析"],"paper":{"id":"social-psy-top-26","title":"Syntactic and Semantic Gender Biases in the Language on Children’s Television: Evidence From a Corpus of 98 Shows From 1960 to 2018","venue":"Psychological Science","year":2025,"url":"https://doi.org/10.1177/09567976251349815","doi":"10.1177/09567976251349815","summary":["儿童电视剧的性别偏见，是否也藏在谁做动作、谁被动承受的句子结构里？","研究分析1960至2018年98部美国节目约6600集剧本，分别检查句法和词义联系。","男性更常出现在行动者位置，这种句法偏差长期稳定，语义偏见却有增强也有减弱。"],"methods":["大规模剧本语料分析","句法与语义比较"]}},{"id":"warm-eco-01","field":"经济学","question":"两个高中生成绩相同，身边有精英教育家庭背景的同学多少不同，申请学校时也可能选得不同吗？","options":["会，同伴也可能改变相同成绩下的申请选择","不会，这类同伴只影响考试，和申请无关","会，但主要表现为入学考试分数同步上升","不会，志愿选择只随学生本人的成绩变化"],"answer":0,"explanation":"成绩相同，申请选择仍可能不同。一项研究利用高中同伴构成的变化，考察身边有父母受过精英教育的同学，是否影响学生申请精英项目的选择。结果显示同伴会参与塑造这些选择，但不能把作用全归为信息传递。","bridge":"把分数固定后再看选择，就能看见同伴网络怎样影响教育机会。","paperId":"social-eco-top-4","tryThis":"写下一个想了解的专业，再找出一个你还不知道的申请要求。","keywords":["同伴效应","教育选择","信息"],"paper":{"id":"social-eco-top-4","title":"First-Generation Elite: The Role of School Social Networks","venue":"American Economic Review","year":2025,"url":"https://doi.org/10.1257/aer.20230582","doi":"10.1257/aer.20230582","summary":["非精英家庭的学生身边多一些精英家庭同学，会改变他们申请大学的选择吗？","研究借评估中的抽签识别同伴作用，再用因果中介分析区分成绩和申请行为。","同伴主要改变的是相同成绩下的申请选择，进入精英项目及后续收入也提高，社会网络因此参与代际延续。"],"methods":["抽签识别","因果中介分析"]}},{"id":"warm-eco-02","field":"经济学","question":"大家都离不开一个社交平台，能直接说明“这个平台存在让大家更幸福”吗？","options":["能，主动花时间使用就已反映全部收益","不能，不用它时被朋友落下的损失也要算","能，只要没有付费，留下就一定净受益","不能，关键只在于平台是否公布用户总数"],"answer":1,"explanation":"喜欢用和希望它存在，是两个问题。带真实激励的大学生实验把不用平台时落在朋友后面的损失也计入，估计的整体收益就可能转负。有些用户宁愿它从未出现，但这不代表所有平台和人群都一样。","bridge":"从“我为什么还在用”，可以走到平台影响非用户的经济学问题。","paperId":"social-eco-top-6","tryThis":"想一个常用平台，各写一条“使用的好处”和“不用会错过的事”。","keywords":["社交平台","网络效应","福利"],"paper":{"id":"social-eco-top-6","title":"When Product Markets Become Collective Traps: The Case of Social Media","venue":"American Economic Review","year":2025,"url":"https://doi.org/10.1257/aer.20231468","doi":"10.1257/aer.20231468","summary":["大家都在用某个平台，是否就意味着它存在让用户整体更好？","研究用有真实激励的大学生实验，除了使用价值，也计入不用平台时落在朋友后面的损失。","传统算法给出正收益，计入非用户外部性后却转负，有些现有用户甚至宁愿平台从未存在。"],"methods":["激励实验","用户与非用户福利测量"]}},{"id":"warm-eco-03","field":"经济学","question":"退休储蓄从“自己申请”改成“默认加入”。追踪研究里，第一年到第三年的储蓄增幅怎样变化？","options":["第三年比第一年更强，且持续等比增长","第一年没有效果，到第三年才突然出现","第一年较明显，到了第三年效果已减弱","三个年度的增幅在每家企业都完全相同"],"answer":2,"explanation":"一个好用的开头，未必等于一样强的长期效果。比较退休计划和追踪面板的研究发现，自动加入第一年的储蓄增幅到第三年会减弱，平均新增储蓄较温和，但储蓄不平等仍下降。短期与长期需要分开看。","bridge":"追问默认选项三年后还剩多少效果，就进入了长期政策评估。","paperId":"social-eco-top-15","tryThis":"看一眼手机的一项默认设置，想想你上次主动改变它是什么时候。","keywords":["默认选项","长期效果","储蓄"],"paper":{"id":"social-eco-top-15","title":"Default Options and Retirement Saving Dynamics","venue":"American Economic Review","year":2025,"url":"https://doi.org/10.1257/aer.20210881","doi":"10.1257/aer.20210881","summary":["退休储蓄自动加入短期很有效，这种收益能维持三年甚至一生吗？","研究结合美国百余个计划和英国代表性面板，再估计带转换成本的生命周期储蓄模型。","一年时的明显增幅到三年已减弱，平均新增储蓄较温和，但储蓄不平等仍下降。"],"methods":["退休计划追踪","生命周期模型估计"]}},{"id":"warm-eco-04","field":"经济学","question":"想让一条消息传开，除了精挑“最有影响力的人”，还有什么办法值得比较？","options":["先找几个彼此最熟悉的传播起点","只选一个朋友最多的人来负责传播","把所有传播起点集中在同一个小圈子","多选几个随机传播起点，再比较覆盖"],"answer":3,"explanation":"找对人有用，多几个起点也可能很有用。扩散模型研究比较了精挑种子和增加随机种子的策略，发现最优选择的优势可能被少量新增随机种子抵消。这并不是说两种办法成本一定相同，也不是任何网络都不用挑人。","bridge":"在网络上比较“挑得准”和“起点多”，能得到意外的传播策略。","paperId":"social-eco-top-17","tryThis":"画两组各六个相连圆点，分别从一个中心点、两个分散点开始涂色传播。","keywords":["信息传播","社交网络","随机策略"],"paper":{"id":"social-eco-top-17","title":"Just a Few Seeds More: The Value of Network Data for Diffusion","venue":"American Economic Review","year":2025,"url":"https://doi.org/10.1257/aer.20180798","doi":"10.1257/aer.20180798","summary":["想让消息传得更广，必须先知道整个社交网络并找出最关键的人吗？","作者分析独立级联扩散模型，并在随机网络及真实网络上做模拟比较。","多随机选择几个起点常能超过最优定点策略；做不到时，最优策略本身通常也只能带来有限传播。"],"methods":["网络扩散模型","真实网络模拟"]}},{"id":"warm-eco-05","field":"经济学","question":"学生能付得起学费，就一定不需要升学辅导了吗？","options":["未必，选什么学校也可能改变拿学位的机会","通常不用，能负担学费就能选对学校","通常不用，大学之间的毕业机会基本相同","未必，但辅导的作用只在于减少申请费用"],"answer":0,"explanation":"入学障碍不只有钱，也有信息与决策。多地点随机试验发现，密集升学辅导提高了低收入学生的学士学位获得率，收益主要来自一开始进入质量更好的学校。它不意味着任何形式的辅导都有相同效果。","bridge":"把“付不起”和“选不到”分开，就能检验辅导究竟帮在哪一步。","paperId":"social-eco-top-23","tryThis":"对一个待学主题写下你已有的资源，再补一个最需要向人请教的问题。","keywords":["升学辅导","教育机会","随机试验"],"paper":{"id":"social-eco-top-23","title":"Increasing Degree Attainment among Low-Income Students: The Role of Intensive Advising and College Quality","venue":"American Economic Review","year":2025,"url":"https://doi.org/10.1257/aer.20240669","doi":"10.1257/aer.20240669","summary":["帮助低收入学生拿学位，除了降低学费，密集升学辅导能带来什么？","多地点随机试验连接行政和调查资料，再用因果森林分析最初大学选择与后续结果。","辅导提高学士学位获得率，收益主要来自最初进入质量更好的学校，不能只把问题看作负担不起。"],"methods":["随机对照试验","因果森林","大学选择分析"]}},{"id":"warm-eco-06","field":"经济学","question":"让一些高年级学生担任“同伴老师”，研究里除了他们自己，谁的行为也跟着改善了？","options":["只影响接受培训的学生本人","他们朋友网络里的同学也减少了违纪","主要改变教师对学生的评分方式","只影响参加过同一门课的低年级生"],"answer":1,"explanation":"被赋予一个角色，影响可能沿着朋友关系走。研究挑选社交联系广、情绪能力较好的高年级学生教学，发现学生老师及其朋友网络的违纪和反社会行为减少。这来自特定选人和教学安排，不能直接推到所有互助活动。","bridge":"把学生变成帮助别人学习的人，能研究一个角色怎样影响朋友网络。","paperId":"exp2200-eco-top-032","tryThis":"用三句话把刚学的一个知识点讲给假想同学听，再标出你解释最卡的一句。","keywords":["同伴教学","角色","朋友网络"],"paper":{"id":"exp2200-eco-top-032","title":"Empowering Adolescents to Transform Schools: Lessons from a Behavioral Targeting","venue":"American Economic Review","year":2025,"url":"https://doi.org/10.1257/aer.20240374","doi":"10.1257/aer.20240374","summary":["让高年级学生当同伴老师，会改变他们自己和朋友的行为吗？","研究选出社交联系广、情绪能力较好的初中高年级学生，赋予教学责任，评估纪律、同伴网络和升学结果。","学生老师及朋友网络的违纪和反社会行为减少，学生老师进入重点高中的机会也提高，赋予角色可能影响整个小群体。"],"methods":["行为干预评估","同伴网络分析"]}},{"id":"warm-lit-01","field":"文学","question":"让故事里原本只能被别人描述的人，改用“我”来讲述。研究十六世纪小说的论文看到了什么可能？","options":["小说中的第一人称主要是近代才出现的","有了第一人称，就应把叙述者等同作者","更早的第一人称也能为边缘人物打开讲述入口","第一人称的主要作用只是缩短人物介绍"],"answer":2,"explanation":"“我”的文学史比熟悉的叙述更长。论文细读十六世纪《小心猫》的三位第一人称叙述者，把这种形式与政治不确定性联系，认为它让边缘人物也能讲述世界。这是具体作品的历史阅读，不是所有第一人称的唯一用途。","bridge":"一个最普通的人称代词，也能连接小说形式与谁有权开口的问题。","paperId":"social-lit-top-0","tryThis":"把“有人走进教室”改写成“我走进教室”，补上只有这个“我”才注意到的细节。","keywords":["第一人称","叙述声音","小说史"],"paper":{"id":"social-lit-top-0","title":"First-Person Prose Narration and William Baldwin’s Beware the Cat (ca. 1553)","venue":"PMLA/Publications of the Modern Language Association of America","year":2025,"url":"https://doi.org/10.1632/s0030812925101399","doi":"10.1632/s0030812925101399","summary":["英语小说里的我，为什么不能只解释成十八世纪个人主义兴起后才有的声音？","作者细读十六世纪《小心猫》的三位第一人称叙述者，并联系当时王位继承与政治的不确定。","第一人称是主动打破第三人称惯例的形式创新，让处于边缘的人也有讲述世界的入口。"],"methods":["小说细读","都铎历史语境分析"]}},{"id":"warm-lit-02","field":"文学","question":"一个戏剧人物为何显得“像活人”？关于福斯塔夫的论文，特别把哪些因素放到一起看？","options":["角色台词的含义与行为动机","作者生平中与角色相似的经历","角色在后世读者中的评价变化","名字、文本版本、印刷传播与舞台身体"],"answer":3,"explanation":"人物不只活在纸面的性格描写里。论文把福斯塔夫的名字、多个文本版本、印刷传播和舞台表演并置，认为鲜活感来自多层再现的累积。这是一条解释人物厚度的路径，不是量化人物好坏的公式。","bridge":"追踪同一个角色怎样被反复演出和传播，也是在研究人物如何形成。","paperId":"social-lit-top-5","tryThis":"选一个熟悉角色，用一句话比较你读到的版本和看到的影视版本。","keywords":["戏剧人物","舞台","版本"],"paper":{"id":"social-lit-top-5","title":"The Persons of the Play: Falstaff and the Thickening of Dramatic Character","venue":"PMLA/Publications of the Modern Language Association of America","year":2025,"url":"https://doi.org/10.1632/s0030812925100928","doi":"10.1632/s0030812925100928","summary":["福斯塔夫为什么像一个活人，戏剧人物的厚度又是怎样被做出来的？","作者把他的多个名字、文本版本、印刷传播和舞台身体放在一起，比较不同媒介的塑造。","人物鲜活来自多层再现不断累积，不能只拿后来小说理论里的圆形人物标准解释戏剧角色。"],"methods":["戏剧人物分析","跨媒介与版本研究"]}},{"id":"warm-lit-03","field":"文学","question":"一本小说被不同地方的读者译写，原来关于改宗的故事变成了尊严与殉难的故事。这提示了什么？","options":["译本也可能重塑群体记忆与故事的重点","差异只来自两种语言的字数与句子长度","译者只需统一术语，就能保留所有叙事重心","出版后的读者处境不会再改变文本意义"],"answer":0,"explanation":"翻译也可能是重新安放故事。论文追踪《雪松谷》在多种犹太语言中的改写，发现原作的反改宗论述，被重塑成历史尊严与殉难叙事。这描述的是这些译本的传播，不等于所有翻译都会采用同样方向。","bridge":"比较译本改了什么，就能把阅读接到跨语言的群体记忆研究。","paperId":"social-lit-top-7","tryThis":"把一句“我回家了”分别写成给家人和给久别故乡的自己看的版本。","keywords":["翻译","群体记忆","传播"],"paper":{"id":"social-lit-top-7","title":"Diasporic World Literature: The Vale of Cedars in the Global Haskalah","venue":"PMLA/Publications of the Modern Language Association of America","year":2025,"url":"https://doi.org/10.1632/s003081292510093x","doi":"10.1632/s003081292510093x","summary":["一本写西班牙秘密犹太人的英国小说，怎样在多国译本中变成不一样的群体记忆？","研究追踪《雪松谷》从伦敦到欧亚非的翻译，比较希伯来语、意第绪语和犹太阿拉伯语改写。","原先反驳改宗论的小说，被重塑为犹太历史尊严与殉难叙事，离散关系使这些不同译本彼此相连。"],"methods":["跨语种翻译史","译本文化比较"]}},{"id":"warm-lit-04","field":"文学","question":"《瓦尔登湖》只是在歌颂远离一切的独居吗？研究梭罗家政实践的论文还看到了什么？","options":["家务的意义主要在于清理与提高效率","家务与园艺也能成为生态关怀的实践","独居生活让人彻底摆脱对社会的依赖","自然写作里的生活劳动只是一种装饰"],"answer":1,"explanation":"一间小屋也可以连接更大的生活关系。论文结合传记、文学史与语言分析，把梭罗的家务、园艺和饲养看作照料栖息地的实践，重读“孤独隐士”形象。这是一种有材料支撑的解释，作品仍容许其他阅读。","bridge":"把书里的家务重新看一遍，日常照料就可能成为生态阅读的线索。","paperId":"social-lit-top-14","tryThis":"找身边一件需要照料的东西，写下它与你之外的两种生命或资源的联系。","keywords":["梭罗","生态阅读","照料"],"paper":{"id":"social-lit-top-14","title":"Thoreau, Gender, and the Ecology of Housework","venue":"PMLA/Publications of the Modern Language Association of America","year":2025,"url":"https://doi.org/10.1632/s0030812925000197","doi":"10.1632/s0030812925000197","summary":["梭罗做家务、园艺和饲养，为什么不是退回私人小屋，而可能是一种社会性的生态实践？","作者结合传记、接受史、酷儿文学史和语言分析，把《瓦尔登湖》放回家政讨论。","照料家与栖息地让他的亲缘和关怀扩大，却不必增加生态占用，也改变了孤独隐士的常见形象。"],"methods":["传记与文本互读","生态与性别批评"]}},{"id":"warm-lit-05","field":"文学","question":"一句诗的意思没变，朗读时的重音却让人感到拉扯。相关莎士比亚论文把这种现象看作什么？","options":["声音的影响主要来自读者误认字义","诗的情感可以仅凭词义确定下来","声音结构也参与了情感的表达","重音变化主要说明诗歌没有固定情感"],"answer":2,"explanation":"诗也会借“怎么读出来”组织感受。论文分析莎士比亚十四行诗中不同重音的拉扯，认为节律的不稳定能强化受伤与焦虑。这个论证来自具体诗句的细读，不是在说某种节奏必然让所有读者产生同一种情绪。","bridge":"给一句诗换个重音，你就能试着听见细读论文关注的声音线索。","paperId":"social-lit-top-17","tryThis":"读两次“我今天真的来了”，分别重读“我”和“真的”，说说语气变了什么。","keywords":["诗歌","重音","节律"],"paper":{"id":"social-lit-top-17","title":"Prosodic Unrest in Shakespeare's Sonnets","venue":"PMLA/Publications of the Modern Language Association of America","year":2025,"url":"https://doi.org/10.1632/s0030812924000968","doi":"10.1632/s0030812924000968","summary":["莎士比亚十四行诗的焦虑，除了字面意思，还能怎样从朗读节奏里感到？","作者区分多种音节强调方式，分析读者准备开口时不同重音如何同时拉扯。","节律中的不稳定强化了暗肤女子及青年相关诗里的受伤情感，声音结构也参与表达而非只是装饰。"],"methods":["韵律分类","音节重音与诗歌细读"]}},{"id":"warm-lit-06","field":"文学","question":"海上故事写“我们一起漂流”，和只写“我独自面对命运”有什么不同？比较航海记与诗歌的论文关注哪一点？","options":["自我应当脱离所有社会关系才能被理解","集体人称主要为了淡化人物间的差异","写“我们”意味着诗中不再有个人经验","自我也可以依赖关系、随处境而变化"],"answer":3,"explanation":"“我们”不只是把“我”变成复数。论文比较十八世纪安森航海记与考珀的诗，讨论集体叙述怎样进入抒情表达，让自我显出依赖关系和情境的一面。这是对相关文本的分析，并非否定个人声音的存在。","bridge":"顺着一个人称的变化，可以读出作品里个体与集体的关系。","paperId":"social-lit-top-19","tryThis":"写下“我完成了这件事”，再改成“我们”，补出原句里被省略的帮助者。","keywords":["我们","抒情","关系中的自我"],"paper":{"id":"social-lit-top-19","title":"Narration in the Key of We : The Voyage and the Grammar of Identity","venue":"PMLA/Publications of the Modern Language Association of America","year":2025,"url":"https://doi.org/10.1632/s003081292400097x","doi":"10.1632/s003081292400097x","summary":["航海叙事常说我们，这种集体人称能给现代自我的故事带来什么不同？","文章比较十八世纪安森航海记与考珀《漂流者》，观察集体叙述如何进入抒情诗。","自我可被写成依赖关系且随情境变化，而非独立封闭个体，连常被视为私人声音的诗也如此。"],"methods":["人称叙事分析","航海与抒情文类比较"]}},{"id":"warm-man-01","field":"工商管理","question":"同样从 100 增到 300，“增长 200%”和“变成 3 倍”会给人完全一样的感觉吗？","options":["未必，表达单位也会改变增长的感觉","一样，读者都会自发换算为相同的单位","未必，因为两种表达的增长额并不相等","一样，只要原数相同就不会产生表达效应"],"answer":0,"explanation":"两个说法在这里算的是同一变化，感觉却未必相同。新闻分析和有激励的选择实验发现，百分比超出常见的零到一百范围时，增长容易显得更大。这是在描述表达方式的影响，不是说每个人都会被误导。","bridge":"把同一变化换个单位，就能检验数字表达怎样影响管理与消费判断。","paperId":"applied-management_top_100-52","tryThis":"把“从 50 到 100”分别写成增加多少、增长百分比、变成几倍。","keywords":["数字表达","增长","判断"],"paper":{"id":"applied-management_top_100-52","title":"Typical Ranges as Scale-Specific Benchmarks: When and Why Percentages Amplify Relative Magnitudes and Their Differences","venue":"Management Science","year":2025,"url":"https://doi.org/10.1287/mnsc.2022.02646","doi":"10.1287/mnsc.2022.02646","summary":["把同一增长写成百分比，为什么可能比写成倍数显得更大，连增幅差异也更醒目？","研究分析新闻数字用法，再做线上实验和带真实激励的选择。","百分比常在零到一百间出现，超出常见范围时感觉更大，说明表达单位本身会改变判断。"],"methods":["文本用法分析","线上与激励实验"]}},{"id":"warm-man-02","field":"工商管理","question":"公司在晋升表里新增“未来潜力”评分。追踪这次制度变化的研究，观察到什么意外结果？","options":["晋升后表现提高，评级也更一致","之后晋升者的实际表现反而较低","晋升后表现不变，但离职显著减少","评级只改变薪酬，不影响晋升选择"],"answer":1,"explanation":"多一个指标，还得看它能否测到有用差异。研究追踪绩效系统新增潜力评级前后的晋升结果，新系统后的晋升者表现反而较低，经理评级区分不足提供了解释。结论不等于所有潜力评估都没价值。","bridge":"追问新增指标能否帮助做对选择，就把管理直觉变成了可检验问题。","paperId":"applied-management_top_100-54","tryThis":"选一个自己想评价的能力，把“有潜力”换成一条能观察到的具体行为。","keywords":["晋升","指标","评价"],"paper":{"id":"applied-management_top_100-54","title":"Promotion Decisions and the Adoption of Explicit Potential Assessment","venue":"Management Science","year":2025,"url":"https://doi.org/10.1287/mnsc.2022.02199","doi":"10.1287/mnsc.2022.02199","summary":["公司额外给员工评估未来潜力，就更能选对晋升者，还是经理可能评不清楚？","研究利用绩效系统新增潜力评级的变化，追踪晋升者之后的实际表现。","新系统后晋升表现反而较低，经理评级区分不足提供解释，增加评价维度不保证选择更准。"],"methods":["绩效系统变化","晋升后表现"]}},{"id":"warm-man-03","field":"工商管理","question":"微博把字数上限放宽后，哪群人的变化在自然实验里更明显？","options":["原本几乎不发帖的人突然贡献最多内容","不同活跃程度的用户都等量增加发帖","原本活跃的人发得更多，单帖点赞也增加","所有原本活跃的人都转向只看不发"],"answer":2,"explanation":"给更多表达空间，不一定让更多人加入。利用微博分批放宽字数上限的自然实验，研究发现活跃用户发得更多、单帖点赞增加，低活跃用户变化较小。总内容增长，可能仍集中在原来少数会说话的人手里。","bridge":"一个平台小功能的变化，可以用来观察谁真正获得了更多表达空间。","paperId":"applied-management_top_100-55","tryThis":"想一个自己很少发言的群聊，写下除“字数不够”外最真实的一个原因。","keywords":["平台设计","参与","自然实验"],"paper":{"id":"applied-management_top_100-55","title":"Too Long, Didn’t Read? The Impact of Length Limits on Microblogging Engagement","venue":"Management Science","year":2025,"url":"https://doi.org/10.1287/mnsc.2021.03629","doi":"10.1287/mnsc.2021.03629","summary":["社交平台放宽发帖字数，会让沉默用户开始表达，还是主要让本来活跃的人说更多？","研究利用中国微博平台分批放宽上限的自然实验，比较发帖和点赞变化。","活跃用户发更多且单帖点赞增加，低活跃者变化小，可能使内容继续集中在少数人。"],"methods":["分批规则变化","平台自然实验"]}},{"id":"warm-man-04","field":"工商管理","question":"给部分电商访客关闭搜索广告后，研究发现一个反差：留着广告时，平台收入和总交易怎样变化？","options":["广告收入和总交易都增加了","广告收入和总交易都减少了","广告收入减少，但总交易增加了","广告收入补过佣金损失，总交易却减少了"],"answer":3,"explanation":"平台赚钱与总交易增加，是不同指标。一项现场实验对部分访客关闭全部搜索广告，发现广告会挤占自然列表并降低总交易，但广告收入能补过佣金损失。这来自一个平台，不能直接套用到所有广告形式。","bridge":"把平台收入与消费者成交分开，就能识别广告效果里容易混淆的两件事。","paperId":"applied-management_top_100-57","tryThis":"想一次点击广告购物的经历，问自己：没有广告时，我会不会本来也买它？","keywords":["搜索广告","指标","替代效应"],"paper":{"id":"applied-management_top_100-57","title":"Does Sponsored Search Advertising Augment Organic Search? Evidence from an E-Commerce Platform","venue":"Management Science","year":2025,"url":"https://doi.org/10.1287/mnsc.2024.04792","doi":"10.1287/mnsc.2024.04792","summary":["搜索广告是在帮电商多卖货，还是把原本会自然成交的生意换成付费入口？","研究在一个平台现场实验，对3%访客关闭全部搜索广告，再比较交易与收入。","广告挤占自然列表并降低总交易，但广告收入补过佣金损失，平台获利与成交增长并不相同。"],"methods":["现场实验","广告关闭对照"]}},{"id":"warm-man-05","field":"工商管理","question":"办贷款的自助页面让人有点焦虑。哪种看似没增加自动化的设计，反而可能帮上忙？","options":["放一个真正能联系到工作人员的入口","把所有说明移到一个独立帮助页面","把填表步骤尽可能合并成一个长页面","增加一个只提供常见问题列表的弹窗"],"answer":0,"explanation":"支持不一定要立刻使用，知道它在也可能有帮助。信用合作社实验邀请用户联系贷款专员，获批贷款的使用增加；配套实验中，焦虑者的信任和体验也改善。研究支持保留可达的人际支持，不是取消自助服务。","bridge":"一个“找得到人”的入口，能连接服务设计与用户焦虑的实验。","paperId":"applied-management_top_100-72","tryThis":"打开一个你常用的工具，找找遇到问题时从哪里联系到真实帮助。","keywords":["服务设计","支持","信任"],"paper":{"id":"applied-management_top_100-72","title":"Mitigating the Negative Effects of Customer Anxiety by Facilitating Access to Human Contact","venue":"Management Science","year":2025,"url":"https://doi.org/10.1287/mnsc.2022.01029","doi":"10.1287/mnsc.2022.01029","summary":["焦虑的客户使用自助贷款会不安，只给一个能联系真人的入口，是否就有帮助？","研究在信用合作社实验邀请联系贷款专员，再用实验室任务检验焦虑、信任与满意。","获批贷款使用增加，焦虑者体验改善，说明保留可达人际支持可以补充自助效率。"],"methods":["现场贷款实验","受控心理实验"]}},{"id":"warm-man-06","field":"工商管理","question":"创业课配了很多数字工具，学生就一定觉得课程更有用吗？","options":["会，课程价值主要随工具数量增长","未必，实践相关和理论实践结合更关键","会，使用频率比课程内容更能解释价值","未必，但主要取决于工具的视觉风格"],"answer":1,"explanation":"工具多不等于教学就到位。对欧洲学生的调查发现，与实践相关、能结合理论和实践的教法更能解释课程是否满足期待，技术只增加少量解释力。这里测的是学生感知，不是实际创业能力的因果变化。","bridge":"把教学方法和技术工具分开比较，就能问出课程究竟在哪儿有帮助。","paperId":"applied-management_regular_100-53","tryThis":"为正在学的一个概念写出一个今天就能用它解释的生活例子。","keywords":["教学设计","数字工具","实践"],"paper":{"id":"applied-management_regular_100-53","title":"Pedagogy over Technology: Evidence from a European Study of Generation Z Students in Entrepreneurship Education","venue":"Administrative Sciences","year":2026,"url":"https://doi.org/10.3390/admsci16090458","doi":"10.3390/admsci16090458","summary":["年轻人喜欢技术不代表课堂越数字化越好，创业课满足期待更依靠教法还是工具？","研究调查欧洲2659名学生，用分层回归比较教学与数字工具新增解释力。","实践相关和理论实践结合最重要，技术只增加少量解释，结论是感知体验而非创业能力试验。"],"methods":["多国学生调查","分层回归"]}},{"id":"warm-fin-01","field":"金融","question":"某公司的声誉指数今天上升了 0.1 点。马上宣布“口碑明显变好”，漏看了什么？","options":["只与昨天的指数数值比较","只看公布了多少位小数","这点变化也可能只是测量噪声","只看指数是否从负数变成正数"],"answer":2,"explanation":"数字动了一点，不代表被测的东西真的变了。研究用状态空间方法平滑声誉指数，估计分析材料中的原始信号约有一成属于噪声。这个比例属于该研究数据，不能当成所有指数都要扣掉一成的固定规则。","bridge":"先问变化有多少可能来自噪声，就接到了金融数据中的信号提取。","paperId":"applied-finance_regular-7","tryThis":"想一个你每天看的数字，写下一种即使真实情况不变也会让它波动的原因。","keywords":["测量误差","信号","噪声"],"paper":{"id":"applied-finance_regular-7","title":"Noise Reduction in a Reputation Index","venue":"International Journal of Financial Studies","year":2018,"url":"https://doi.org/10.3390/ijfs6010019","doi":"10.3390/ijfs6010019","summary":["声誉指数的小幅起伏可能来自测量误差，怎样区分真正变化和数据中的噪声？","研究用状态空间和卡尔曼滤波逐步平滑指数，再与低通滤波方法比较。","分析中的原始信号约有一成属于噪声，说明微小变化不能直接当作声誉改善或恶化。"],"methods":["状态空间模型","卡尔曼滤波"]}},{"id":"warm-fin-02","field":"金融","question":"房产专家预测明年的房价，会往同行的平均答案靠拢，还是刻意与众不同？一项调查分析看到了什么？","options":["专家会更紧密地追随同行的平均预测","专家通常会停止给出房价具体数字","专家的预测习惯在危机前后保持不变","房价预测中，偏离同行共识的行为更常见"],"answer":3,"explanation":"专家也可能不想和别人报出同一个答案。研究比较二〇〇六至二〇一二年的房价与新屋开工预测，发现房价预测中偏离共识的行为更常见，危机前后还会变化。偏离平均数不代表更准确，也不能证明每位专家都刻意求异。","bridge":"比较每个人与同行平均预测的距离，就能研究专家怎样处理共识。","paperId":"applied-finance_regular-2","tryThis":"先独立估一估房间的长度，再看别人怎么估，留意自己是否想改答案。","keywords":["专家预测","共识","求异"],"paper":{"id":"applied-finance_regular-2","title":"House Price Forecasts, Forecaster Herding, and the Recent Crisis","venue":"International Journal of Financial Studies","year":2012,"url":"https://doi.org/10.3390/ijfs1010016","doi":"10.3390/ijfs1010016","summary":["预测房地产市场时，专家是否会向同行共识靠拢，还是故意给出更不一样的答案？","研究分析2006至2012年房价与新屋开工调查，把每个人的预测与群体共识比较。","房价预测中偏离共识的行为更常见，而且金融危机前后这种倾向发生变化。"],"methods":["专家预测调查","羊群行为检验"]}},{"id":"warm-fin-03","field":"金融","question":"以生物多样性为主题的基金，听起来很美好。比较二十四只这类基金的研究，观察到怎样的短期表现？","options":["短期跑输基准，收费也相对较高","短期跑赢基准，收费也相对较高","短期跑输基准，收费却相对较低","短期跑赢基准，收费却相对较低"],"answer":0,"explanation":"主题说的是关注方向，表现仍要另看。对二十四只相关基金的探索性比较发现，它们多数较新、规模较小，短期表现跑输基准且收费更高。短记录不能决定长期结果，也不能据此否定全部同类基金。","bridge":"把一个吸引人的标签拆成收益、风险和费用，就有了可比较的研究问题。","paperId":"applied-finance_regular-22","tryThis":"找一个带“绿色”标签的日常产品，写下这个词说明了什么、又没说明什么。","keywords":["可持续标签","费用","基准比较"],"paper":{"id":"applied-finance_regular-22","title":"Biodiversity Mutual Funds and ETFs: Characteristics, Performance, Risk, and Fees","venue":"International Journal of Financial Studies","year":2026,"url":"https://doi.org/10.3390/ijfs14050117","doi":"10.3390/ijfs14050117","summary":["以保护生物多样性为主题的基金，实际收益、风险和收费是否配得上可持续标签？","研究探索性比较24只共同基金和交易所基金，整理其规模、基准表现、费用和评级。","这些基金多数很新、规模小且评级较高，但短期跑输基准、收费更高，结论仍受短记录限制。"],"methods":["主题基金比较","风险费用核算"]}},{"id":"warm-fin-04","field":"金融","question":"黄金行情一热闹，就怕“别人都赚到了，只有我没赶上”。这在一项投资者调查里，对应哪种心理？","options":["信息越热闹，越不愿参考其他人的选择","害怕错过，把从众和下单决定联系起来","越担心错过，越会推迟所有购买决定","从众只改变观看时长，不关联交易决定"],"answer":1,"explanation":"热闹可能把“我想要”悄悄换成“我怕落下”。对七百二十七名越南投资者的问卷研究发现，从众与损失厌恶都关联害怕错过，这种心理又联系投资决定。它描述的是统计关系，不是诊断每一次买入的真实动机。","bridge":"把怕错过的感觉单独拎出来，就能研究行情热闹时的决策心理。","paperId":"applied-finance_regular-31","tryThis":"想一个最近想跟风购买的东西，补完这句话：如果没人知道，我还会想要它吗？","keywords":["害怕错过","从众","黄金"],"paper":{"id":"applied-finance_regular-31","title":"The Role of Fear of Missing out (FOMO), Loss Aversion, and Herd Behavior in Gold Investment Decisions: A Study in the Vietnamese Market","venue":"International Journal of Financial Studies","year":2025,"url":"https://doi.org/10.3390/ijfs13030175","doi":"10.3390/ijfs13030175","summary":["黄金行情热闹时，害怕错过机会会不会把损失厌恶与从众变成更仓促的下单？","研究调查727名越南投资者，用结构方程比较心理因素，并检查不同提示信息下的差异。","损失厌恶和从众都与怕错过有关，这种心理又联系到投资决定，风险提示可改变关系强弱。"],"methods":["投资者调查","结构方程","多群组比较"]}},{"id":"warm-fin-05","field":"金融","question":"一家公司公布了坏消息，股价却没接着跌，甚至上涨。哪种解释能让这个反差说得通？","options":["坏消息通常会立即抬高公司资产价值","公告里只要出现损失，短期回报就必为负","大家此前预期更糟，部分坏消息已被消化","公告日的成交量本身就会保证股价上涨"],"answer":2,"explanation":"价格反应看的是新信息，不只是消息听起来好不好。围绕美国能源企业困境公告的事件研究，在部分公告后窗口观察到正的中位收益，可能与坏消息已提前被消化有关。这不是公告后一定上涨的交易规律。","bridge":"给消息标出时间线，就能研究价格究竟在何时回应了哪些信息。","paperId":"applied-finance_regular-29","tryThis":"给一条旧新闻画三个时间点：事情发生、传闻出现、正式公布。","keywords":["市场预期","事件研究","信息"],"paper":{"id":"applied-finance_regular-29","title":"Corporate Financial Distress and Equity Market Contagion: Evidence from Energy Sector Collapses in the U.S. Stock Market","venue":"International Journal of Financial Studies","year":2026,"url":"https://doi.org/10.3390/ijfs14050129","doi":"10.3390/ijfs14050129","summary":["能源企业宣布陷入财务困境，股价是否只会继续下跌，还会传染到更广的市场？","研究围绕51家美国能源公司的困境公告，计算异常收益并做秩检验与面板分析。","部分公告后的窗口中位收益为正，未见普遍市场扰乱，市场可能已提前消化部分坏消息。"],"methods":["事件研究","符号秩检验","面板回归"]}},{"id":"warm-fin-06","field":"金融","question":"公司宣布并购，网上有分析长帖、表情包和追涨帖。研究发现，哪类讨论更能透露交易会不会撤回？","options":["互动量最高的帖，不需要看具体写了什么","粉丝最多的账号，对事件的第一条短评","同一条立场被重复转发的次数","认真讨论交易细节的长帖，情绪也含信息"],"answer":3,"explanation":"热闹不等于有料。研究把并购相关帖子的情绪与后续交易结局相连，在纳入股价、新闻和分析师信号后，积极讨论仍对应较低撤回概率；信息主要来自认真讨论交易的长帖。这是概率线索，不是按情绪买卖的保证。","bridge":"把热闹帖子与有内容的讨论分开，就能研究网上情绪究竟藏着什么信息。","paperId":"applied-finance_top_modern-10","tryThis":"找一条讨论某件事的帖子，分别圈出事实、推测和纯粹情绪各一处。","keywords":["并购","网络讨论","信息含量"],"paper":{"id":"applied-finance_top_modern-10","title":"Can Social Media Inform Corporate Decisions? Evidence from Merger Withdrawals","venue":"The Journal of Finance","year":2025,"url":"https://doi.org/10.1111/jofi.13508","doi":"10.1111/jofi.13508","summary":["一项并购宣布后，网上的投资者讨论能否透露这笔交易最后会不会被撤回？","研究分析相关帖子的情绪，并把股价反应、新闻和分析师建议等其他信号纳入比较。","更积极的讨论对应更低撤回概率，信息主要来自认真讨论交易的长帖，而非表情包或追涨帖。"],"methods":["社交媒体情绪分析","并购事件研究"]}},{"id":"warm-cs-01","field":"计算机","question":"你家平时一天用电 5 度，电表却记下一次 500 度。预测明天时，最值得警惕什么？","options":["一个异常点把预测拖偏","中位数会自动升到五百","记录变多就无法计算均值","这证明每天用电都在增长"],"answer":0,"explanation":"异常值可能来自故障，也可能是真实的特殊事件，不能直接当作日常规律。相关论文让模型更重视局部相似的数据，在一组实际电力数据上改善了预测；这不等于所有异常点都该删除。","bridge":"电表里一个离谱数字，就能连到一篇研究抗异常预测的论文。","paperId":"cs-regular-002","tryThis":"写下 5、5、5、5、500，分别算平均数和找中位数，看看谁被拖得更远。","keywords":["异常值","预测","稳健性"],"paper":{"id":"cs-regular-002","title":"A robust maximum correntropy forecasting model for time series with outliers","venue":"PeerJ Computer Science","year":2023,"url":"https://doi.org/10.7717/peerj-cs.1251","doi":"10.7717/peerj-cs.1251","summary":["用电等时间序列中几个异常点就可能拖偏预测，怎样减少这些点的干扰？","作者用最大相关熵衡量局部相似，建立自回归模型，再通过半定松弛估计参数。","汉中实际电力数据中，平均百分比误差优于所比较的深层学习方法，显示这种局部相似度能抗异常值。"],"methods":["最大相关熵","鲁棒序列回归"]}},{"id":"warm-cs-02","field":"计算机","question":"投票时不想让计票员看见每个人选了谁，却想算出总票数。哪条思路真的有人研究？","options":["先公开原始选票再删姓名","让加密的票也能参与求和","把原始票集中交给一个人","等投票结束再公开单人票"],"answer":1,"explanation":"同态加密允许对密文做特定运算，再解密得到对应结果，像隔着信封完成一部分计算。这篇电子投票论文还结合签名与多阶段加密；隐私、身份核验和防篡改需要一起设计。","bridge":"不拆信封也能数票，是这篇投票方案背后的关键想法。","paperId":"cs-regular-015","tryThis":"画出“选民→加密选票→汇总→解密总数”，圈出哪一步需要知道单人的选择。","keywords":["同态加密","电子投票","隐私"],"paper":{"id":"cs-regular-015","title":"An electronic voting scheme based on homomorphic encryption and decentralization","venue":"PeerJ Computer Science","year":2023,"url":"https://doi.org/10.7717/peerj-cs.1649","doi":"10.7717/peerj-cs.1649","summary":["电子选票在传输中可能被篡改，投票过程又不能提前泄露结果，怎样同时保护隐私与可核验性？","作者结合 Paillier 同态加密、选民签名和计票中心二次加密，形成去中心化方案。","安全分析支持匿名、唯一和可验证等性质，计算效率也优于所比较的一套旧方案。"],"methods":["同态加密","签名双层选票"]}},{"id":"warm-cs-03","field":"计算机","question":"想把一段秘密文字藏进图片，图片又尽量看不出变化。先做哪件事能减轻负担？","options":["把同一段文字多藏几遍","把图片先缩到更少像素","先把要藏的文字压缩变短","把原始文字改成大写字母"],"answer":2,"explanation":"需要嵌入的信息越少，就越有余地减少对图片的改动。相关论文把压缩和多通道、多层嵌入结合，在所测条件下兼顾容量与画质；看起来相似并不等于能抵抗所有侦测。","bridge":"一张看起来没变化的图，可以连到信息隐藏与压缩研究。","paperId":"cs-regular-019","tryThis":"把“哈哈哈哈哈哈哈哈”改写成“哈×8”，比较两种表达用了多少字符。","keywords":["信息隐藏","压缩","图像"],"paper":{"id":"cs-regular-019","title":"New deep data hiding and extraction algorithm using multi-channel with multi-level to improve data security and payload capacity","venue":"PeerJ Computer Science","year":2022,"url":"https://doi.org/10.7717/peerj-cs.1115","doi":"10.7717/peerj-cs.1115","summary":["把秘密信息藏进图片时，藏得越多越容易被看出，怎样在容量和外观之间取得更好平衡？","作者把信息分到多通道多层图片，结合最低位修改、Huffman 压缩和异或处理。","所测载荷下，视觉相似与质量指标优于旧方案，显示能在较难察觉的情况下容纳较多信息。"],"methods":["多层图像隐写","压缩与位替换"]}},{"id":"warm-cs-04","field":"计算机","question":"打车时走到路口上车，偶尔比坚持在门口上车更快。算法该一起考虑什么？","options":["只让乘客的步行距离最短","只让司机的绕行距离最短","只选当前停着车最多的点","步行距离和司机绕行成本"],"answer":3,"explanation":"对乘客省一步，可能意味着司机多绕一大圈。相关研究把乘客、司机、上车点和目的地一起计算，并限制可接受的步行距离，在实验中降低了总成本；不是要求所有乘客都多走路。","bridge":"挪几十米上车的日常选择，也能成为网约车优化论文。","paperId":"cs-regular-022","tryThis":"在纸上画一条单行道和两个上车点，分别标出你要走的路和司机要绕的路。","keywords":["路径优化","上车点","成本权衡"],"paper":{"id":"cs-regular-022","title":"Pick-up point recommendation strategy based on user incentive mechanism","venue":"PeerJ Computer Science","year":2023,"url":"https://doi.org/10.7717/peerj-cs.1692","doi":"10.7717/peerj-cs.1692","summary":["网约车不一定非要开到用户脚下，怎样推荐步行可接受的上车点，同时节省司机绕行？","作者把乘客、司机、上车点和目的地共同建模，用激励机制与成本指标选择位置。","实验中，推荐降低订单总成本并提高司机效率，同时考虑用户最大步行距离。"],"methods":["四方位置匹配","激励式上车点推荐"]}},{"id":"warm-cs-05","field":"计算机","question":"一个识别智能设备的模型说自己很准。你最想加哪项测试，看看它下个月还能不能用？","options":["前几周训练，留出后几周测试","每周数据混合后再随机切分","同一周内按设备随机分组测试","把采集当天分成上午和下午"],"answer":0,"explanation":"随机混合数据可能让训练集和测试集处在很接近的环境。按时间留出后来的数据，更能检验模型面对变化是否稳定。相关设备识别论文按周评测，但几周表现稳定仍不能保证永远不变。","bridge":"“上周很准，下周呢”正是这篇设备识别研究关心的问题。","paperId":"cs-regular-026","tryThis":"把最近十次学习记录按时间分成前七次和后三次，想一个只用前七次预测后三次的规则。","keywords":["时间切分","泛化","数据变化"],"paper":{"id":"cs-regular-026","title":"Improved temporal IoT device identification using robust statistical features","venue":"PeerJ Computer Science","year":2024,"url":"https://doi.org/10.7717/peerj-cs.2145","doi":"10.7717/peerj-cs.2145","summary":["设备流量随时间变化，物联网识别模型常要反复重训，能否选择更稳定的统计特征？","作者用载荷长度描述设备行为，结合随机森林与一对其余分类，并按周切分数据评测。","公开数据各周准确率保持在 80% 以上，自采数据也改善，说明长期评测比随机切分更能检验稳定性。"],"methods":["载荷长度特征","跨周设备识别"]}},{"id":"warm-cs-06","field":"计算机","question":"数据科学课把编程和统计教得很好，就能放心让毕业生处理任何真实问题了吗？","options":["再增加编程与统计课的练习量","补上领域背景、伦理及结果沟通","让所有项目使用统一标准数据","让课程项目全部改为独立完成"],"answer":1,"explanation":"同一份数据怎样收集、谁会被遗漏、结果怎样影响他人，都不只靠代码回答。一项美国本科课程分析发现，计算与统计较强，领域背景、伦理和沟通常较弱；这是对所考察项目的课程观察。","bridge":"会写代码之外缺什么，也能用课程资料做成一篇研究。","paperId":"cs-regular-033","tryThis":"选一个你常用的推荐软件，写下“它可能漏掉哪类人”和“漏掉会有什么后果”。","keywords":["数据伦理","课程分析","领域背景"],"paper":{"id":"cs-regular-033","title":"Undergraduate data science degrees emphasize computer science and statistics but fall short in ethics training and domain-specific context","venue":"PeerJ Computer Science","year":2021,"url":"https://doi.org/10.7717/peerj-cs.441","doi":"10.7717/peerj-cs.441","summary":["数据科学本科发展很快，但学生是否只学会编程统计，却缺少专业背景、伦理和沟通训练？","作者按两套教育框架制定评分表，检查美国部分四年制院校课程。","多数项目计算与统计较强、领域伦理沟通较弱，授予学位的院系也显著影响课程结构。"],"methods":["课程框架评分","数据科学教育分析"]}},{"id":"warm-phy-01","field":"物理","question":"水滴顺着斜面滑下，路线却有点古怪。除了重力和摩擦，还可能漏看什么？","options":["水滴温度改变带来的浮力变化","水滴内部流动产生的自发推进","滑动时产生的静电力","空气湿度对重力方向的改变"],"answer":2,"explanation":"液滴与表面接触、分离时可能带电，静电力也会影响运动。研究者拍下液滴轨迹，再反推受力，发现低介电常数基底上的影响明显；这不是说每一滴水都由静电主导。","bridge":"一滴水没有走直线，就能引出液滴自发带电的物理论文。","paperId":"phy-top-016","tryThis":"画一滴沿斜面下滑的水，用三个箭头分别标出重力、阻力和你猜的额外作用力。","keywords":["液滴","静电","受力分析"],"paper":{"id":"phy-top-016","title":"Spontaneous charging affects the motion of sliding drops","venue":"Nature Physics","year":2022,"url":"https://doi.org/10.1038/s41567-022-01563-6","doi":"10.1038/s41567-022-01563-6","summary":["水滴顺着表面滑落却走出复杂路线，传统黏性与接触线解释是否遗漏了其他力？","作者拍摄倾斜表面上的液滴轨迹，用运动方程反推出受力，并比较不同基底与液体。","低介电常数基底上静电力显著改变运动，因此描述水和其他液滴时也必须纳入自发带电。"],"methods":["液滴轨迹测量","静电受力分析"]}},{"id":"warm-phy-02","field":"物理","question":"全球多台仪器一起找某种暗物质信号，最后没找到。这个结果能说明什么？","options":["排除仪器涉及的所有暗物质理论","确定暗物质不与任何普通物质相互作用","确认信号只在其他季节才可能出现","可限制这类模型的一部分范围"],"answer":3,"explanation":"没有信号也能排除“若参数在这里，本该看见”的一部分可能。相关研究分析全球磁强计一个月的数据，未发现显著共同信号，因而限制特定域壁模型；并未否定所有暗物质。","bridge":"“什么也没发现”也能产出有用的暗物质实验结果。","paperId":"phy-top-023","tryThis":"写一句“抽屉里没找到钥匙”，再补上你究竟检查了哪些抽屉，体会结论范围的变化。","keywords":["暗物质","零结果","证据范围"],"paper":{"id":"phy-top-023","title":"Search for topological defect dark matter with a global network of optical magnetometers","venue":"Nature Physics","year":2021,"url":"https://doi.org/10.1038/s41567-021-01393-y","doi":"10.1038/s41567-021-01393-y","summary":["如果暗物质集中成比地球还大的薄壁，它扫过各地仪器时，是否会留下相互对应的短暂信号？","作者联合全球光学原子磁强计，分析连续一个月的数据，寻找按特定速度穿过网络的信号模式。","没有发现统计显著的共同信号，因此给这类轴子状粒子域壁暗物质模型施加了实验限制。"],"methods":["全球磁强计网络","瞬态信号搜索"]}},{"id":"warm-phy-03","field":"物理","question":"用粒子束撞击金属靶来产生新粒子，把靶做得更粗就一定产得更多吗？","options":["未必，产物也可能困在材料里","通常如此，增加体积就会同比增加逃逸量","通常如此，束流强度相同就只需比较质量","未必，靶的几何形状只会改变生产成本"],"answer":0,"explanation":"靶既提供碰撞机会，也可能让已经产生的低能粒子损失掉。结合具体质子束分布的计算发现，缩小钨靶半径反而提高了低能粒子产额；最佳尺寸依赖束流和所要收集的粒子。","bridge":"“材料多一点反而少产一点”，正是这篇靶尺寸研究的趣味。","paperId":"phy-regular-007","tryThis":"画一束箭头穿过厚薄两块靶，再给“产生”和“逃出”分别画两条路径。","keywords":["粒子束","靶设计","优化"],"paper":{"id":"phy-regular-007","title":"The study of high-efficiency pion production","venue":"The European Physical Journal Plus","year":2025,"url":"https://doi.org/10.1140/epjp/s13360-025-06164-9","doi":"10.1140/epjp/s13360-025-06164-9","summary":["用质子束撞击钨靶产生低能π介子时，靶越粗是否就一定产得越多？","研究结合COMET实验近期测到的质子束分布，计算不同圆柱靶半径下的低能粒子产额。","计算显示，把靶半径减到4毫米反而可提高约六成效率，继续增粗会损失低能粒子，说明靶尺寸需要配合束流调整。"],"methods":["粒子产额优化","束流与靶几何计算"]}},{"id":"warm-phy-04","field":"物理","question":"名画的红色颜料慢慢变样，物理学家可以拿什么当线索，而不只是看颜色？","options":["只比较手机照片的红色数值","测颜料发光和微观化学变化","只凭画作年代判断降解原因","只把所有褪色归为光照过强"],"answer":1,"explanation":"颜料受光激发后发出的光，能够透露材料状态。研究把真实画作的无损光谱与人工老化样品对照，发现湿度、油性介质和颜料成分共同影响降解；不能把所有褪色都归给同一种原因。","bridge":"美术馆里一块变色的红，也能连到光谱与材料老化论文。","paperId":"phy-regular-014","tryThis":"找一件颜色褪去的旧物，写下光照、湿度、摩擦三个可能原因，并选一个你会先比较的条件。","keywords":["光谱","颜料","材料老化"],"paper":{"id":"phy-regular-014","title":"Deeper insights into the photoluminescence properties and (photo)chemical reactivity of cadmium red (CdS1−xSex) paints in renowned twentieth century paintings by state-of-the-art investigations at multiple length scales","venue":"The European Physical Journal Plus","year":2022,"url":"https://doi.org/10.1140/epjp/s13360-022-02447-7","doi":"10.1140/epjp/s13360-022-02447-7","summary":["名画里的镉红为什么会变色，颜料发出的光又怎样揭示它受潮或老化的情况？","研究结合九幅画作的无损光谱、微观成像和人工老化样品，比较颜料发光与化学变化。","湿度会改变特征发光，油性介质、湿度和硒含量共同影响光降解，也解释了部分画作上出现的硫酸镉和草酸镉。"],"methods":["多尺度光谱与成像","人工老化实验"]}},{"id":"warm-phy-05","field":"物理","question":"同样大小的一滴水，在表面上摊得更平，通常说明这个表面怎样了？","options":["对水的排斥通常更强","表面一定更适合所有包装","更容易被水润湿了","水滴的体积一定变大了"],"answer":2,"explanation":"水滴在表面边缘形成的接触角越小，通常越容易铺开。相关研究用氧等离子体处理聚乙烯醇薄膜，测到接触角下降；这是对该材料表面性质的测量，不等于所有包装性能都一起改善。","bridge":"看一滴水是趴着还是鼓着，就能连到包装薄膜表面研究。","paperId":"phy-regular-016","tryThis":"在纸上画一滴鼓起的水和一滴摊平的水，用线标出它们边缘接触表面的角度。","keywords":["接触角","亲水性","表面处理"],"paper":{"id":"phy-regular-016","title":"Microwave plasma discharge-assisted surface modification of PVA films: coatings and food packaging","venue":"The European Physical Journal Plus","year":2022,"url":"https://doi.org/10.1140/epjp/s13360-022-03443-7","doi":"10.1140/epjp/s13360-022-03443-7","summary":["食品包装常用的聚乙烯醇薄膜，能否用低成本处理让表面更容易被水润湿？","研究用微波氧等离子体处理薄膜，再以显微成像、表面成分和接触角测量比较处理前后。","处理后表面更粗糙，水滴接触角明显下降，显示表面更亲水，为调整涂层与包装材料性质提供了办法。"],"methods":["等离子体表面处理","接触角与表面光谱"]}},{"id":"warm-phy-06","field":"物理","question":"某过程从消耗 1 份能量变成 2 份，听起来翻倍了。判断整体影响，还缺什么？","options":["是否换一种单位继续写翻倍","是否把翻倍再换成百分比","能否只比较变化前后的比例","总输入到底有多少份能量"],"answer":3,"explanation":"相对增幅很大，新增部分仍可能只占总量的一小点。托卡马克边缘模拟中，能量脉冲时离子与电子交换变强，但新增交换不足总输入的百分之一，因此不能只凭“变强很多”判断全局影响。","bridge":"从“翻倍”追问到“占多少”，能读懂这篇聚变模拟的关键边界。","paperId":"phy-regular-077","tryThis":"写下总预算 1000 元、某项开支从 1 元涨到 2 元，分别算增幅和新增开支占比。","keywords":["相对变化","绝对影响","能量交换"],"paper":{"id":"phy-regular-077","title":"Ion–electron energy transfer in kinetic and fluid modelling of the tokamak scrape-off layer","venue":"The European Physical Journal Plus","year":2021,"url":"https://doi.org/10.1140/epjp/s13360-021-02060-0","doi":"10.1140/epjp/s13360-021-02060-0","summary":["托卡马克边缘突然涌入能量时，把电子当普通流体，会不会漏算离子与电子之间的能量交换？","研究用一维动力学程序模拟稳态和能量脉冲，再与流体近似比较交换强度及其沿空间的变化。","稳态差别很小，脉冲时动力学交换更强，但新增部分占总输入能量不足1%，不能只凭相对增幅就判断整体影响很大。"],"methods":["等离子体动力学模拟","动力学与流体模型比较"]}},{"id":"warm-math-01","field":"数学","question":"测试灯泡寿命，实验结束时有些灯还亮着。统计时应该怎么处理它们？","options":["记下至少已经存活的时长","把仍亮着的灯全部当坏了","认定仍亮着的灯永远不坏","只留下实验中已经坏的灯"],"answer":0,"explanation":"还亮着并非没有信息：它的寿命至少超过了观察时长。这叫删失数据。相关可靠性论文把未失效样本纳入估计，并允许强度分阶段变化；具体计算仍依赖所选分布和模型条件。","bridge":"一只没熄灭的灯泡，也能连到不完整寿命数据的数学研究。","paperId":"math-regular-001","tryThis":"画三条寿命线：两条标出失效时间，一条在观察终点画箭头，写下第三条已经告诉了你什么。","keywords":["删失数据","寿命","可靠性"],"paper":{"id":"math-regular-001","title":"Analysis of stress-strength reliability with m-step strength levels under type I censoring and Gompertz distribution","venue":"AIMS Mathematics","year":2024,"url":"https://doi.org/10.3934/math.20241484","doi":"10.3934/math.20241484","summary":["产品承受的载荷和自身强度都在变化，失效记录又不完整时，怎样估计承载强度高于载荷的概率？","作者用 Gompertz 分布描述载荷与强度，允许强度分阶段变化，并把到预定时刻还未失效的样本也纳入估计。","模拟给出不同可靠性估计与区间的表现，真实数据也展示这套方法如何处理不完整失效记录。"],"methods":["最大似然估计","Bootstrap区间"]}},{"id":"warm-math-02","field":"数学","question":"拍到一张模糊照片，为什么不能保证靠“倒着计算”完美还原每个细节？","options":["计算机只能把图越算越糊","微小测量噪声可能被放大","照片里有噪声就完全没信息","倒着计算只适用于黑白图"],"answer":1,"explanation":"有些倒推问题不稳定：输入只差一点点，答案就可能差很远。相关论文研究带噪声的波动方程初态，通过截去高频项稳定计算；这是牺牲部分细节换取可靠近似，并非万能修复术。","bridge":"照片越修越出现怪纹路，能帮助理解这篇逆问题论文的出发点。","paperId":"math-regular-020","tryThis":"计算 1÷0.1 和 1÷0.01，看看靠近零的小变化怎样变成很大的结果差别。","keywords":["逆问题","噪声放大","稳定化"],"paper":{"id":"math-regular-020","title":"Approximation of the initial value for damped nonlinear hyperbolic equations with random Gaussian white noise on the measurements","venue":"AIMS Mathematics","year":2022,"url":"https://doi.org/10.3934/math.2022698","doi":"10.3934/math.2022698","summary":["测量里混入随机噪声后，倒推阻尼非线性波动方程的初始状态，微小误差可能被放大。","作者先证明这种倒推不稳定，再截去高频傅里叶项，构造较稳定的近似解。","在真实解满足先验约束时，近似误差和收敛速度都能估计，数值例子也验证了稳定化效果。"],"methods":["傅里叶截断","正则化误差估计"]}},{"id":"warm-math-03","field":"数学","question":"从 6、10、15 里各取一次，三个数相乘会得到什么？","options":["一个乘积为 900 的完全立方数","一个无法写成整数平方的合数","一个乘积为 900 的完全平方数","一个乘积为 600 的偶数"],"answer":2,"explanation":"6×10×15＝900＝30²。拆开看，质因数 2、3、5 都恰好出现两次。相关论文进一步研究：随机抽出多少整数后，才很可能挑出一组乘积为平方数，并给出了精确阈值结果。","bridge":"把几个数凑成平方，只差一步就走到了随机整数的前沿问题。","paperId":"math-top-010","tryThis":"把 6、10、15 分别拆成质因数，用相同颜色把成对出现的因数圈起来。","keywords":["质因数","完全平方数","随机阈值"],"paper":{"id":"math-top-010","title":"The sharp threshold for making squares","venue":"Annals of Mathematics","year":2018,"url":"https://doi.org/10.4007/annals.2018.188.1.2","doi":"10.4007/annals.2018.188.1.2","summary":["随机抽出一批整数，什么时候才很可能找到若干个数，让它们的乘积恰好是完全平方数？","作者把质因数是否成对出现编码成随机超图，用自校正鞅追踪图中核心部分的大小。","他们确定了事件发生概率突然上升的精确阈值，解决了两项关于随机整数成平方的猜想。"],"methods":["随机超图","自校正鞅"]}},{"id":"warm-math-04","field":"数学","question":"一个整数通过了你列出的所有余数检查，能不能立刻断定它一定能由某套规则生成？","options":["能，通过有限种检查就能覆盖所有结构","能，局部条件总会保证整体可以实现","不能，因为余数对整数结构没有任何帮助","不能，还可能存在没检查的障碍"],"answer":3,"explanation":"通过必要条件，不等于已经满足充分条件。阿波罗圆堆积研究发现，一些整数虽然通过原先的余数限制，仍然不会作为圆的曲率出现；新的障碍推翻了原有的局部到整体猜想。","bridge":"“每项都合格，整体却不行”，是这篇圆堆积论文揭示的意外。","paperId":"math-top-021","tryThis":"写下“能被 2 整除”是“能被 4 整除”的必要条件，再找一个通过前者却没通过后者的数。","keywords":["必要条件","圆堆积","反例"],"paper":{"id":"math-top-021","title":"The local-global conjecture for Apollonian circle packings is false","venue":"Annals of Mathematics","year":2024,"url":"https://doi.org/10.4007/annals.2024.200.2.6","doi":"10.4007/annals.2024.200.2.6","summary":["阿波罗圆堆积里的圆曲率要满足一些余数条件，但通过这些检查的大整数就一定会出现吗？","作者用二次和四次互反律寻找更深的限制，分析薄群带来的新障碍。","许多圆堆积仍会漏掉整族满足原条件的整数，说明原来的局部到整体猜想是错的。"],"methods":["互反律分析","反例构造"]}},{"id":"warm-math-05","field":"数学","question":"下面哪一行最像一个左右读起来都一样的简单图案？","options":["● ▲ ■ ▲ ●","● ▲ ■ ● ▲","■ ● ▲ ▲ ●","▲ ■ ● ● ■"],"answer":0,"explanation":"第一行从两边往中间看，符号依次相同，这就是回文式对称。数学家还会把这种想法搬到二维，用替换和拼接规则生成图案；相关论文研究可生成的图案类型，而不只是手工画对称花纹。","bridge":"一行左右对称的小图案，可以连到二维回文与图案语法研究。","paperId":"math-regular-014","tryThis":"先写任意三个符号，再按相反顺序补回去，做出你自己的六格回文图案。","keywords":["回文","对称","生成规则"],"paper":{"id":"math-regular-014","title":"Two-dimensional array grammars in palindromic languages","venue":"AIMS Mathematics","year":2024,"url":"https://doi.org/10.3934/math.2024841","doi":"10.3934/math.2024841","summary":["二维回文图案看起来有对称性，能否只靠一套替换规则自动生成，而不是逐像素去画？","作者设计以数组为终结符的正则和上下文无关语法，用拼接条件控制推导。","这些语法能生成多种回文图案，文章明确了语法类别的层级与封闭性，并生成一些 kolam 图案。"],"methods":["数组重写语法","形式语言分析"]}},{"id":"warm-math-06","field":"数学","question":"一串数是 1、1、2、3、5、8，规则是把前两项相加。下一项是多少？","options":["11","13","15","16"],"answer":1,"explanation":"下一项是 5＋8＝13。用前面几项决定后面一项，叫递推规则。相关论文调整参数，把 Fibonacci、Lucas 等多类数列放进共同框架，再推导恒等式；这里的小算题只是进入这个框架的入口。","bridge":"熟悉的 1、1、2、3、5，能一路连到统一多类数列的研究。","paperId":"math-regular-031","tryThis":"把起点改成 2、1，继续用前两项相加，写出接下来的四项并和原数列比较。","keywords":["递推","Fibonacci","数列"],"paper":{"id":"math-regular-031","title":"Some new identities of a type of generalized numbers involving four parameters","venue":"AIMS Mathematics","year":2022,"url":"https://doi.org/10.3934/math.2022718","doi":"10.3934/math.2022718","summary":["Fibonacci、Lucas 等经典数列都有递推规则，它们的许多恒等式能否从同一套公式得到？","作者用四个参数定义 Horadam 型广义数，推导显式表达式与两类数列间的混合递推。","新恒等式涵盖多种经典数列，也把已有文献中的一些公式统一为特殊取值。"],"methods":["递推数列","参数化恒等式"]}},{"id":"warm-elec-01","field":"电子","question":"芯片做测试，大量时间都在等外部设备一条条发指令。提速还能从哪里下手？","options":["每执行一步就再次请求确认","保留通信流程只缩短结果文件","压缩指令并交给芯片自行调度","把重复指令全部分开发送"],"answer":2,"explanation":"慢的不一定是计算，也可能是来回传话。相关闪存测试研究把重复指令做成模板，再压缩后交给芯片调度，实测总时间减少；主要收益来自减少流程开销，而不是让每个电路动作都变快。","bridge":"少来回说几遍同样的话，也能成为芯片测试提速的论文。","paperId":"applied-electronics_regular-1","tryThis":"把“开、关、开、关、开、关”写成一条重复指令，数数少传了多少个动作说明。","keywords":["指令压缩","芯片测试","通信开销"],"paper":{"id":"applied-electronics_regular-1","title":"Entropy-Guided BIST Instruction Set Compression for Auto-CP Embedded Flash Testing","venue":"Electronics","year":2026,"url":"https://doi.org/10.3390/electronics15204733","doi":"10.3390/electronics15204733","summary":["汽车芯片的闪存测试要不断等待外部设备发指令，这些来回通信是否能压缩掉？","研究把重复指令做成模板，再用霍夫曼编码压缩，让芯片一次接收后自行调度。","实测总测试时间减少15%，外部交互占比也下降，主要收益来自流程开销减少。"],"methods":["片上自测试","指令压缩"]}},{"id":"warm-elec-02","field":"电子","question":"微电网遇到风光发电忽高忽低，为什么不把电池一直用到空？","options":["因为只需照顾当前这一分钟","因为所有调节方式成本都一样","因为明天发电量总能完全预测","还要给后续变化留余量并算成本"],"answer":3,"explanation":"眼前便宜的调节方式，可能耗掉后面更需要的储能。相关论文把日前计划与日内滚动调整结合，按成本安排设备，同时限制电池电量范围；案例中的改善依赖具体系统与预测条件。","bridge":"手机都知道别把电量用尽，微电网也把余量写进调度研究。","paperId":"applied-electronics_regular-7","tryThis":"假设电池有 10 格电，今晚还需 4 格，先写下现在最多能动用多少格，再想想预测不准时怎么办。","keywords":["储能","滚动调度","电量约束"],"paper":{"id":"applied-electronics_regular-7","title":"Dual-Timescale Robust Rolling Optimal Scheduling of Microgrid Considering Regulation Priority","venue":"Electronics","year":2026,"url":"https://doi.org/10.3390/electronics15204745","doi":"10.3390/electronics15204745","summary":["新能源微电网供需经常变化，储能、燃气设备和购电应该按什么次序补缺口？","研究建立日前与日内滚动优化，按边际成本排调节顺序，并限制储能荷电状态。","案例中成本、排放和储能运行都有改善，但结论依赖所建系统与预测条件。"],"methods":["鲁棒模型预测控制","滚动调度"]}},{"id":"warm-elec-03","field":"电子","question":"换上新一代 Wi-Fi，视频还是会卡。下面哪件事仍然值得检查？","options":["信号强弱和同时抢网的设备数","只看包装标出的理论最高速率","只看手机是否显示连接已成功","只看路由器是否标着新代际"],"answer":0,"explanation":"协议更新不等于无线环境中的竞争和弱信号消失。相关 Wi-Fi 7 研究在所测单链路条件下发现，这两项会增加延迟；它关闭了多链路功能，也不能据此判断所有满载和多链路场景。","bridge":"“明明换了新路由怎么还卡”，也能连到真实网络测量论文。","paperId":"applied-electronics_regular-42","tryThis":"列出此刻家里可能在联网的三台设备，再标出你离路由器最近和最远的两个位置。","keywords":["Wi-Fi","网络竞争","延迟"],"paper":{"id":"applied-electronics_regular-42","title":"Wi-Fi 7 Streaming Stability: A Multi-Band, Multi-Bitrate Performance Assessment","venue":"Electronics","year":2026,"url":"https://doi.org/10.3390/electronics15204730","doi":"10.3390/electronics15204730","summary":["新一代Wi-Fi更快，但播放卡顿究竟受信号、频段、码率还是用户拥挤影响更多？","研究用实物测试和网络仿真逐项改变条件，关闭多链路功能，只观察单链路。","弱信号和竞争用户增加延迟，结果是低码率非饱和场景，不能推为多链路满载表现。"],"methods":["无线测试床","网络仿真"]}},{"id":"warm-elec-04","field":"电子","question":"把铜箔按特定图案贴在牛仔布上，除了装饰，还可能做到什么？","options":["不论图案都能挡住全部无线电","让特定一段微波较难穿过去","只改变外观而不影响电磁波","把全部入射频率放大相同比例"],"answer":1,"explanation":"重复排列的导电图案能像筛子一样选择频率。相关研究在铜箔和牛仔布组成的平面样品中测到约十吉赫兹的阻带；这还没有证明弯折穿戴后的效果，更不等于屏蔽所有无线信号。","bridge":"牛仔布上的一排铜十字，可以连到选择性电磁屏障研究。","paperId":"applied-electronics_regular-47","tryThis":"画一排重复的十字图案，旁边写下“让哪段频率少通过”，把它和“挡住全部信号”区分开。","keywords":["频率选择","微波","织物电子"],"paper":{"id":"applied-electronics_regular-47","title":"Textile-Based Band-Stop FSS Design for X-Band Applications","venue":"Electronics","year":2026,"url":"https://doi.org/10.3390/electronics15204719","doi":"10.3390/electronics15204719","summary":["低价铜箔贴在牛仔布上，能否过滤一段微波，作为织物里的选择性电磁屏障？","研究仿真十字单元，制作平面阵列，再测自由空间透射、入射角和极化。","约10吉赫兹附近出现阻带，但未单测布料等材料贡献，也尚未验证弯曲穿戴性能。"],"methods":["全波仿真","织物频率选择表面"]}},{"id":"warm-elec-05","field":"电子","question":"一种加密程序在台式电脑上最快，能直接说它在小型物联网芯片上也最快吗？","options":["能，算法相同就与硬件无关","能，代码更短就必然运行更快","不能，平台和实现都会影响结果","不能，小芯片只能比较耗电量"],"answer":2,"explanation":"处理器指令、内存限制和程序实现都会改变速度与占用空间。相关轻量加密试验测的是 x86 平台上的几种参考实现，因此它能描述这套测试的取舍，不能直接变成全部物联网芯片的排名。","bridge":"电脑上跑得快，搬到小芯片未必；这篇论文就提醒了测试平台边界。","paperId":"applied-electronics_regular-20","tryThis":"给“这个算法最快”补上三个空：在哪台设备、哪种实现、处理多大的输入。","keywords":["轻量加密","基准测试","硬件平台"],"paper":{"id":"applied-electronics_regular-20","title":"A Descriptive Pilot Study of Performance and Resource Utilization of Lightweight Cryptography Implementations","venue":"Electronics","year":2026,"url":"https://doi.org/10.3390/electronics15204751","doi":"10.3390/electronics15204751","summary":["轻量加密算法面向小设备，但在同一平台上，不同实现的速度与占用空间怎样取舍？","研究在x86环境测三种参考实现的吞吐、延迟、代码和内存，而非直接测微控制器。","Ascon实现更快，另两种部分配置代码较小，结果不能直接当作物联网芯片上的通用排名。"],"methods":["实现基准测量","资源开销比较"]}},{"id":"warm-elec-06","field":"电子","question":"一个模型在热过载条件下预测零件寿命很准。想知道它能否用于其他工况，哪项测试最直接？","options":["同批热过载数据换一种随机切分","同种热过载条件下再测一批零件","同种热过载条件下加测更多时点","换到不同负载或老化条件再检验"],"answer":3,"explanation":"过热老化只是零件可能经历的一种环境。相关功率晶体管论文综合电压、温度与状态变化，在特定热过载数据上改善预测；要用于其他负载或真实设备，还需要验证能否跨条件工作。","bridge":"预测零件还能撑多久，关键不只准不准，还要看在哪种老化条件下准。","paperId":"applied-electronics_regular-0","tryThis":"选一件常用电器，写下高温、反复开关、潮湿三种环境，猜猜哪些会改变它的老化方式。","keywords":["剩余寿命","老化","跨条件验证"],"paper":{"id":"applied-electronics_regular-0","title":"Fractional Long-Range Dependence Multi-Mode for Remaining Useful Life Prognosis of IGBT Under DC Voltage Control","venue":"Electronics","year":2026,"url":"https://doi.org/10.3390/electronics15204744","doi":"10.3390/electronics15204744","summary":["功率晶体管逐步老化时会在不同运行状态间切换，这让剩余寿命很难准确预测。","研究把两处电压和温度合成健康指标，用马尔可夫模型描述状态切换，并加入长期老化过程。","在NASA老化数据上，这套方法比四种对照预测更准，但验证仍来自特定热过载数据。"],"methods":["马尔可夫状态模型","分数阶寿命预测"]}},{"id":"warm-ai-01","field":"人工智能","question":"教 AI 分猫狗，每张照片请人标注都花钱。预算有限时，怎样选下一批照片更有研究价值？","options":["挑可能最能改善当前模型的样本","只挑当前判断最确定的典型照片","按照片文件大小从大到小挑选","在同一张典型照片上重复标注"],"answer":0,"explanation":"主动学习不是把每张图都问一遍，而是决定哪些标签更值得买。相关研究预先训练选样策略，在固定标注预算的实验中达到或超过比较方法；具体选法仍要用任务数据检验。","bridge":"“只够问老师十个问题，问哪十个”也对应真实的主动学习论文。","paperId":"ai-regular-001","tryThis":"拿一项你正在学的内容，写三个问题，圈出那个一旦答清就能解决最多困惑的问题。","keywords":["主动学习","标注预算","选样"],"paper":{"id":"ai-regular-001","title":"Pre-Training Acquisition Functions by Deep Reinforcement Learning for Fixed Budget Active Learning","venue":"Neural Processing Letters","year":2021,"url":"https://doi.org/10.1007/s11063-021-10476-z","doi":"10.1007/s11063-021-10476-z","summary":["数据每标注一条都要花钱，预算用完后不能再补，怎样挑选最能改善分类的样本？","作者把采样策略当成强化学习问题，先训练一个决定哪些数据值得获取的函数。","固定标注预算的实验中，这个预训练策略达到或超过所比较的主动学习方法。"],"methods":["深度强化学习","固定预算选样"]}},{"id":"warm-ai-02","field":"人工智能","question":"五个朋友一起选活动，推荐榜全是多数人喜欢的密室，另一个人怕黑。系统还该考虑什么？","options":["只按所有活动的平均热度排序","成员公平与推荐内容的多样性","只让人数最多的偏好决定全部","只给每种密室换不同封面图"],"answer":1,"explanation":"给一群人推荐，既要避免总让少数成员妥协，也要避免选项全长一个样。相关群体推荐研究把公平与多样性一起加入算法，在所测综合指标上改善表现；如何权衡仍需要明确目标。","bridge":"朋友聚会别总有人被委屈，这个小烦恼也能进入推荐算法论文。","paperId":"ai-regular-004","tryThis":"写下三位朋友各自最喜欢和最不想参加的活动，找一个不是任何人雷区的共同选项。","keywords":["群体推荐","公平","多样性"],"paper":{"id":"ai-regular-004","title":"DFGR: Diversity and Fairness Awareness of Group Recommendation in an Event-based Social Network","venue":"Neural Processing Letters","year":2023,"url":"https://doi.org/10.1007/s11063-023-11376-0","doi":"10.1007/s11063-023-11376-0","summary":["为一群人推荐活动时，只顾共同热门选择可能忽略部分成员，也可能让推荐过于相似。","作者在活动社交网络中同时加入公平性与多样性，构造群体推荐方法。","与比较的公平推荐算法相比，综合指标有所提高，展示同时平衡两项目标的可行性。"],"methods":["公平多样推荐","群体偏好建模"]}},{"id":"warm-ai-03","field":"人工智能","question":"让同一个图像模型每次临时关掉少量单元，再反复判断一张图。结果忽猫忽狗，提示什么？","options":["说明这张图一定属于训练样本之外","说明猫狗在现实中出现概率相同","这个输入附近的判断可能不稳定","说明多数结果已经给出可靠概率"],"answer":2,"explanation":"这种反复随机关闭单元再预测的做法叫 MC-dropout，可用结果分散程度估计不确定性。相关实验中，高不确定性点常靠近类别分界；它提供线索，但不是模型错误或真实概率的绝对证明。","bridge":"让 AI 多答几遍，看它会不会改口，可以连到不确定性估计研究。","paperId":"ai-regular-012","tryThis":"写一个你拿不准的二选一问题，列出会让你改答案的两条新信息，体会“边界附近”的含义。","keywords":["不确定性","MC-dropout","决策边界"],"paper":{"id":"ai-regular-012","title":"Illustrative Discussion of MC-Dropout in General Dataset: Uncertainty Estimation in Bitcoin","venue":"Neural Processing Letters","year":2021,"url":"https://doi.org/10.1007/s11063-021-10424-x","doi":"10.1007/s11063-021-10424-x","summary":["分类器的一个分数未必说明它有多确定，MC-dropout 能否找出最靠近类别分界的样本？","作者用随机丢弃网络单元反复预测，先检查合成数据，再测试比特币交易数据。","不确定性较高的点集中在类别分界附近，比特币任务中引入该方法也优于标准模型。"],"methods":["MC-dropout不确定性","交易数据实验"]}},{"id":"warm-ai-04","field":"人工智能","question":"AI 把同一张图从“猫”改判成“狗”，解释热图却几乎没变。最合理的反应是什么？","options":["位置相同就说明两种理由相同","热图相似能证明新判断更正确","只要框到主体就算解释了改判","追问热图是否真的解释了改判"],"answer":3,"explanation":"解释图应该帮助理解判断为何变化，不能只提供一张看起来合理的彩图。相关论文比较原图和微小扰动后的对抗样本，发现某类显著图未清楚区分两种判断；结论针对所测解释规则。","bridge":"AI 圈出“我看了这里”，不一定说明“我为什么这样想”。","paperId":"ai-regular-014","tryThis":"想象两个人给出相反答案却圈出同一行证据，各写一句你会怎样追问他们的理由。","keywords":["可解释性","显著图","对抗样本"],"paper":{"id":"ai-regular-014","title":"Evaluation of the Explanatory Power Of Layer-wise Relevance Propagation using Adversarial Examples","venue":"Neural Processing Letters","year":2023,"url":"https://doi.org/10.1007/s11063-023-11166-8","doi":"10.1007/s11063-023-11166-8","summary":["如果一张图片被微小扰动骗成另一类，解释方法应当说明理由为何改变，而不是仍画出近乎相同的热区。","作者比较原图与对应对抗样本的逐层相关传播图，同时分析轮廓和统计差异。","不同分解规则都未让两种判断的显著图清楚分开，说明这些图未必能解释模型真正改变的理由。"],"methods":["对抗样本解释检验","显著图统计"]}},{"id":"warm-ai-05","field":"人工智能","question":"AI 在白天街景里认车很准，换成夜间画面就失误。多做迁移学习一定能救回来吗？","options":["未必，迁入不合适的信息还可能更差","会，只要先前训练数据足够多就行","会，识别同类物体不需要考虑光线变化","未必，迁移只适合完全相同的图片"],"answer":0,"explanation":"数据环境改变后，原来好用的线索可能不再可靠。迁移带来负面效果叫负迁移。相关综述指出，分布差异很大时它仍是难题；这不是否定迁移学习，而是提醒先检查新旧任务是否合适。","bridge":"白天学会的本领，夜里可能失灵；这正连到领域适配的研究难点。","paperId":"ai-regular-019","tryThis":"选一项你会的技能，写一个新场景，再分别列一条能迁过去和一条可能反而误导你的经验。","keywords":["领域适配","负迁移","分布变化"],"paper":{"id":"ai-regular-019","title":"A Survey on Adversarial Domain Adaptation","venue":"Neural Processing Letters","year":2022,"url":"https://doi.org/10.1007/s11063-022-10977-5","doi":"10.1007/s11063-022-10977-5","summary":["模型换到分布不同的新领域就容易出错，对抗式领域适配现有哪些设计，又为什么可能负迁移？","作者逐一比较相关方法的网络结构与训练目标，梳理度量学习、多判别器等路线。","综述指出分布差异大时负迁移仍未解决，并建议将聚类启发式加入既有结构继续检验。"],"methods":["对抗领域适配综述","结构目标比较"]}},{"id":"warm-ai-06","field":"人工智能","question":"游戏 AI 的真实试玩次数有限，有一种办法是先学个“游戏模拟器”。它接下来能做什么？","options":["把画面编码直接当成动作答案","在模拟出的环境轨迹中练习策略","只复现旧轨迹，不模拟新动作","用模拟高分代替真实环境评测"],"answer":1,"explanation":"世界模型学习环境会怎样变化，让智能体在模拟经验中练习。相关论文缩小这种模型，在相同交互预算的 Atari 测试中仍保持接近比较方案的表现；模拟有效的前提也包括模型不能偏离环境太远。","bridge":"让 AI 在“脑内小游戏”里练习，就能连到紧凑世界模型论文。","paperId":"ai-regular-020","tryThis":"选一个小游戏，写下“当前画面＋一个动作→下一步变化”的三组例子，做一个纸上世界模型。","keywords":["世界模型","强化学习","模拟经验"],"paper":{"id":"ai-regular-020","title":"Smaller World Models for Reinforcement Learning","venue":"Neural Processing Letters","year":2023,"url":"https://doi.org/10.1007/s11063-023-11381-3","doi":"10.1007/s11063-023-11381-3","summary":["世界模型能让智能体在想象里练习，但模型本身常很大，是否能明显缩小而不损失游戏水平？","作者用向量量化自编码器表示图像、卷积记忆网络预测动态，再让策略只在模拟经验中训练。","Atari 上，相同十万次交互预算下，更小的模型仍达到与 SimPLe 相近的表现，消融支持各项设计。"],"methods":["紧凑世界模型","模拟经验强化学习"]}},{"id":"warm-med-01","field":"医学","question":"声音到了耳朵，还得向大脑“报信”。耳内的感官细胞靠哪一步参与这件事？","options":["向听觉神经传递信号","让耳道分泌更多耳垢","让外耳廓朝声音转动","调节鼓膜两侧的气压"],"answer":0,"explanation":"听见不只是接住振动，还要把信息传出去。耳内感官毛细胞的信号传递需要otoferlin蛋白；它不足时，可能造成先天耳聋。一项针对这类耳聋的基因治疗研究，正是围绕这个环节展开，而非处理所有听力问题。","bridge":"从耳朵怎样“报信”，可以走进一种遗传性耳聋的基因研究。","paperId":"applied-medicine_top-48","tryThis":"用30秒把“声波—耳内感官细胞—听觉神经—大脑”画成一条传话路线。","keywords":["听觉","毛细胞","信号传递"],"paper":{"id":"applied-medicine_top-48","title":"DB-OTO Gene Therapy for Inherited Deafness.","venue":"The New England journal of medicine","year":2026,"url":"https://doi.org/10.1056/nejmoa2400521","doi":"10.1056/nejmoa2400521","summary":["OTOF基因异常让儿童几乎听不到声音，耳内基因治疗能否恢复自然声学听觉？","研究给12名患儿在一耳或双耳输注DB-OTO，检查24周听阈及听觉脑干反应。","听力整体改善，其中三人听觉敏感度达到正常，但仍属单组首次人体研究。"],"methods":["首次人体基因治疗","听阈测量"]}},{"id":"warm-med-02","field":"医学","question":"成年人长高告一段落后，身高会像身份证号码一样一直不变吗？","options":["会，骨骼成熟后就永久固定","不会，中年以后也可能下降","只有体重改变时才会改变","只有发生骨折后才会改变"],"answer":1,"explanation":"成年身高不是终身固定的数字。一项纳入2343名40至79岁成人的研究，便追踪了每年的身高下降，并分析它与血压、血小板数量的关系。这里的长期变化不能用随手量一次来判断，更不能靠血小板数自行解释原因。","bridge":"“以后还会不会变矮”也能连到成年身高变化的长期研究。","paperId":"applied-medicine_regular_disease100-32","tryThis":"花30秒想想：比较两次身高记录时，除了数字，还需要记下哪些测量条件？","keywords":["成年身高","长期变化","人体观察"],"paper":{"id":"applied-medicine_regular_disease100-32","title":"Platelet count and hypertension as indicators of height loss in the general population: A prospective study.","venue":"PloS one","year":2024,"url":"https://doi.org/10.1371/journal.pone.0314527","doi":"10.1371/journal.pone.0314527","summary":["中年以后身高逐渐降低，容易测到的血小板数量与血压，是否能提供相关线索？","研究比较2343名成人的年度身高变化，按有无高血压分别分析血小板关联。","血小板较多只在高血压人群中对应较少身高下降，但这并不证明增加血小板就能保护身高。"],"methods":["成人队列","分层风险分析"]}},{"id":"warm-med-03","field":"医学","question":"疟原虫想从一个人“搭便车”到另一个人，主要借助什么？","options":["说话时呼出的飞沫","一起吃饭用过的餐具","受感染的雌性按蚊叮咬","握手时短暂的皮肤接触"],"answer":2,"explanation":"疟疾主要通过受感染的雌性按蚊叮咬传播，病原体是疟原虫，并非普通的握手或一起吃饭就会传播。这个传播环节也带来研究灵感：乌干达一项试验研究了处理过的婴儿背巾，在已有蚊帐保护的基础上能否再减少感染。","bridge":"一只蚊子的“搭便车”路线，竟连到了抱娃背巾的医学试验。","paperId":"applied-medicine_top_100-62","tryThis":"用30秒画出“感染者—蚊子—另一个人”的箭头，再标出你觉得可研究的一个环节。","keywords":["疟原虫","按蚊","传播途径"],"paper":{"id":"applied-medicine_top_100-62","title":"Permethrin-Treated Baby Wraps for the Prevention of Malaria.","venue":"The New England journal of medicine","year":2025,"url":"https://doi.org/10.1056/nejmoa2501628","doi":"10.1056/nejmoa2501628","summary":["婴儿已有蚊帐保护，母亲再用浸过杀虫剂的背巾抱孩子，能否进一步减少疟疾？","研究在乌干达随机分配真实或假处理背巾，每四周重新处理，并随访母婴24周。","处理背巾减少儿童临床疟疾，但这是在有蚊帐基础上的特定用品干预。"],"methods":["双盲随机试验","杀虫背巾干预"]}},{"id":"warm-med-04","field":"医学","question":"设计一份“手术体验成绩单”，谁最适合补上医护人员未必知道的疼痛感受？","options":["做过很多同类手术的医生","熟悉手术设备的工程师","看过全部病历的统计人员","亲身经历这段过程的患者"],"answer":3,"explanation":"疼痛体验不能只靠旁观者代答。一项制定手术安全评价指标的共识研究发现，患者与医护人员对疼痛相关指标的评分有所不同。把两方声音都纳入，才更容易看见专业判断和亲身体验各自关注的事。","bridge":"一张体验成绩单，连着患者如何参与制定医疗评价标准。","paperId":"applied-medicine_regular_epmc-22","tryThis":"回想一次乘车体验，用30秒分别写下司机和乘客可能最在意的一个指标。","keywords":["患者体验","共同决策","评价指标"],"paper":{"id":"applied-medicine_regular_epmc-22","title":"Moving towards a core measures set for patient safety in perioperative care: An e-Delphi consensus study.","venue":"PloS one","year":2024,"url":"https://doi.org/10.1371/journal.pone.0311896","doi":"10.1371/journal.pone.0311896","summary":["围手术期安全研究使用的指标五花八门，哪些指标值得大家一起优先报告？","研究先综合已有综述，再让专家和患者参加两轮线上德尔菲讨论，评估重要性与可行性。","不同手术阶段均形成共识指标，但患者对疼痛的评价与专业人员不同，说明专业人员不能代替患者表达体验。"],"methods":["伞状综述","线上德尔菲共识"]}},{"id":"warm-med-05","field":"医学","question":"在平板上拿笔走迷宫，看起来是手在动，实际上还可能有哪些关节一起配合？","options":["肩关节和肘关节也会参与","主要由指尖移动，肩肘都保持固定","肩部参与移动，肘部则必须保持不动","手腕参与移动，肩和肘则不需要参与"],"answer":0,"explanation":"一条笔尖轨迹，背后可能是多个关节在协作。研究者专门设计了需要肩、肘共同参与的平板迷宫任务，发现它能记录卒中后手臂运动的空间和时间特点。同样走到终点，路径是否越界、速度如何变化，也能讲出不同的故事。","bridge":"一笔走完的小迷宫，也能连到手臂协调与运动康复的研究。","paperId":"applied-medicine_regular_disease100-47","tryThis":"用30秒在纸上画一个大一点的方形迷宫，慢慢走一遍，留意肩、肘和手腕分别怎样动。","keywords":["手臂协调","迷宫任务","运动轨迹"],"paper":{"id":"applied-medicine_regular_disease100-47","title":"Using a tablet to understand the spatial and temporal characteristics of complex upper limb movements in chronic stroke.","venue":"PloS one","year":2024,"url":"https://doi.org/10.1371/journal.pone.0311773","doi":"10.1371/journal.pone.0311773","summary":["机器人测卒中后的手臂功能很贵，普通平板上的迷宫任务能否捕捉细微运动困难？","研究让20名慢性卒中患者与20名对照用触笔走不同复杂度迷宫，记录轨迹和速度。","患者更常越界，迷宫变复杂时误差更明显，说明低成本设备能提供空间与时间两类测量。"],"methods":["平板迷宫任务","动作指标比较"]}},{"id":"warm-med-06","field":"医学","question":"医学AI输入的“图片”，一定得是相机或扫描设备拍出来的吗？","options":["是，视觉模型的输入都得先经过相机","未必，也可能是表格数据转换的图像","是，表格只有先打印拍照才能用于模型","未必，但只能用医生手绘的示意图"],"answer":1,"explanation":"模型吃进去的“图片”，不一定是拍出来的。有研究把696名乳腺癌患者的临床表格转成图像，再借用现成视觉网络提取特征、预测后续事件。这是一种数据表示方法，并不是让普通照片具备诊断能力。","bridge":"把数字换个摆法，就能连接到医学AI中的数据表示研究。","paperId":"applied-medicine_regular_epmc-39","tryThis":"用30秒把三个数字画成三个高低不同的小柱子，看看同一份数据怎样换了一种样子。","keywords":["表格图像化","迁移学习","医学AI"],"paper":{"id":"applied-medicine_regular_epmc-39","title":"Prediction of breast cancer Invasive Disease Events using transfer learning on clinical data as image-form.","venue":"PloS one","year":2024,"url":"https://doi.org/10.1371/journal.pone.0312036","doi":"10.1371/journal.pone.0312036","summary":["乳腺癌临床信息通常在表格里，把它变成图像后，能不能借用现成视觉模型做预测？","研究将696名患者的数据转成图片，用预训练网络取特征，再用支持向量机分类。","研究建立了五年和十年侵袭性疾病事件预测方案，但模型不是从真正的病理图片中识别癌症。"],"methods":["表格图像化","迁移学习","支持向量机"]}},{"id":"warm-nurse-01","field":"护理学","question":"你本来按颜色给卡片分类，突然改成按形状分。大脑主要在忙什么？","options":["辨认声音从哪个方向传来","回忆很多年前发生的事情","从旧规则切换到新的规则","判断两个颜色是否一样亮"],"answer":2,"explanation":"跟着新要求换规则，是认知灵活性的一种表现，属于执行功能。护理研究也会关注这些日常能力：一篇综述合并42项试验，发现有氧运动对健康中老年人的认知灵活性等能力有帮助，但不能据此推算某个人的效果。","bridge":"一次换规则的小卡顿，也能连到护理学里的认知功能研究。","paperId":"nursing-39326271","tryThis":"用30秒把身边三样东西先按大小排，再按名称字数排，留意换规则的那一瞬间。","keywords":["认知灵活性","执行功能","系统综述"],"paper":{"id":"nursing-39326271","title":"Effects of aerobic exercise on executive function of healthy middle-aged and older adults: A systematic review and meta-analysis.","venue":"International Journal of Nursing Studies","year":2024,"url":"https://doi.org/10.1016/j.ijnurstu.2024.104912","doi":"10.1016/j.ijnurstu.2024.104912","summary":["随着年龄增长，人们切换任务、记住临时信息和克制冲动的能力会下降，有氧运动能帮上忙吗？","研究汇总42项随机对照试验，合并2881名45岁以上健康成年人的数据，比较运动与对照组的表现。","运动有助于改善这三类能力，但不同训练安排的效果不同，不能只用一个运动方案套给所有人。"],"methods":["系统综述","Meta分析"]}},{"id":"warm-nurse-02","field":"护理学","question":"两个人今天都处理了十件事。只看这个数字，能知道谁更忙、更累吗？","options":["能，十件事的负担完全一样","能，写在表格前面的更忙","能，完成得快的必然更轻松","不能，还要看任务和主观负担"],"answer":3,"explanation":"任务数量和感到的负担，不是同一个东西。一项让护士连续记录班次、并收集患者反馈的研究发现，主观工作量也参与了工作量与漏护的关系。它提供了关联线索，并不意味着只要调整心态就能解决人手问题。","bridge":"“事情一样多，怎么累得不一样”也是护理工作量的研究问题。","paperId":"nursing-39396481","tryThis":"用30秒列出今天两件事，分别标注“花了多久”和“费了多少心力”。","keywords":["主观工作量","日记研究","护理体验"],"paper":{"id":"nursing-39396481","title":"Unraveling the impact of subjective and objective workload on patient experience: Mediation and moderation by missed nursing care assessments in a nested multisource diary design.","venue":"International Journal of Nursing Studies","year":2025,"url":"https://doi.org/10.1016/j.ijnurstu.2024.104919","doi":"10.1016/j.ijnurstu.2024.104919","summary":["同样的工作量，为什么有些班次会漏做护理，患者的感受也更差？","研究让141名护士连续记录五个早班的经历，并结合627名患者的反馈和客观工作量，分析它们怎样共同关联漏护。","漏护并不只随客观任务多少变化，护士感到的负担也会改变这种关系，患者与护士对漏护的评价同样会影响就医体验。"],"methods":["每日日记研究","多来源数据","混合模型"]}},{"id":"warm-nurse-03","field":"护理学","question":"想让自己更容易开始读书，下面哪种做法最像行为科学里的“助推”？","options":["提前把书翻到下一页放在桌上","规定没读书就不能进入房间","给每次阅读发一大笔现金奖","替自己决定以后只准读哪本"],"answer":0,"explanation":"助推会调整选择环境，让某个行动更顺手，同时保留选择空间；环境线索、提醒都是例子。护理学的一篇综述也整理了面向老人的健康助推，但并非每种做法都有效，不能把一个小提醒当成万能办法。","bridge":"从桌上摊开的书，可以一路问到护理学怎样设计健康提醒。","paperId":"nursing-39486107","tryThis":"花30秒把接下来想学的一页打开，放到伸手就能碰到的位置。","keywords":["助推","环境线索","行动门槛"],"paper":{"id":"nursing-39486107","title":"Using nudges to promote health among older adults: A scoping review.","venue":"International Journal of Nursing Studies","year":2025,"url":"https://doi.org/10.1016/j.ijnurstu.2024.104946","doi":"10.1016/j.ijnurstu.2024.104946","summary":["通过提醒、默认选项等小调整来影响选择，能不能帮助老人改善健康？","研究梳理18篇有关老年健康的文章，把不同的“助推”做法按它们影响决策的方式分类。","助推已用于接种、饮食和减少过度医疗等场景，多数研究有积极发现，但并非每一种做法都有效，长期效果还待确认。"],"methods":["范围综述","助推策略分类"]}},{"id":"warm-nurse-04","field":"护理学","question":"患者已获准转出ICU，却还没转走。除了病情，还可能卡在哪一环？","options":["患者过去接受过哪些治疗","合适床位和团队交接是否到位","这类疾病通常需要几次检查","患者之前的病情评估有多复杂"],"answer":1,"explanation":"“可以转出”只是流程中的一站，下个病区还要有合适床位，团队也要接上信息。澳大利亚三家医院的访谈研究发现，床位、信息系统和协调都可能卡住转出。排队背后，常常还有一套看不见的协作过程。","bridge":"医院里的一次等床，连着护理团队如何协调患者流转的研究。","paperId":"nursing-39536612","tryThis":"用30秒画出网购从下单到收货的三个环节，圈出一个可能让整条链停住的地方。","keywords":["患者流转","团队协调","流程瓶颈"],"paper":{"id":"nursing-39536612","title":"Who gets the bed: Factors influencing the intensive care exit block: A qualitative study.","venue":"International Journal of Nursing Studies","year":2025,"url":"https://doi.org/10.1016/j.ijnurstu.2024.104949","doi":"10.1016/j.ijnurstu.2024.104949","summary":["患者已经可以转出重症监护室，为什么却还在里面等床，迟迟走不了？","研究在澳大利亚三家医院访谈59名工作人员，并结合现场记录和转出文件，分析病床分配与协作过程。","合适床位不足、系统不互通和转出标准不一致都会卡住流程，角色分工清楚、提早协调则有助于顺利转出。"],"methods":["多地点质性观察","访谈与文件分析"]}},{"id":"warm-nurse-05","field":"护理学","question":"新App能自动生成一份记录，却又要求手动填三份表。判断它是否减负，还得看什么？","options":["只看自动生成了多少份记录","只看增加了多少个实用功能","全部操作花费的时间与心力","只看处理一份记录有多快"],"answer":2,"explanation":"一个环节省时，不等于整份工作更轻松。一篇汇总213篇综述的护理研究发现，数字技术能帮助任务执行和信息管理，也可能增加工作量、疲劳与挫败感。评价工具要看完整流程，不能只数它新增了几个功能。","bridge":"一款App到底省不省事，也能成为数字护理技术的研究题。","paperId":"nursing-39603090","tryThis":"花30秒回想一个常用App，分别说出它替你省掉和额外增加的一步操作。","keywords":["数字护理","工作负担","用户体验"],"paper":{"id":"nursing-39603090","title":"Digital technologies in nursing: An umbrella review.","venue":"International Journal of Nursing Studies","year":2025,"url":"https://doi.org/10.1016/j.ijnurstu.2024.104950","doi":"10.1016/j.ijnurstu.2024.104950","summary":["护理工作越来越数字化，电子记录、远程照护等工具到底帮了护士，还是增加了负担？","研究者再汇总213篇已有综述，比较不同数字技术对工作、职业健康和患者自主权等方面的影响。","技术能帮助管理信息和完成任务，但也常增加工作量、疲劳与挫败感，不能把数字化一概视为减负。"],"methods":["伞状综述","叙述综合"]}},{"id":"warm-nurse-06","field":"护理学","question":"给小朋友设计一份研究问卷，怎样才更接近“以儿童为中心”？","options":["照搬成人问卷，只缩小字号","只问家长，避免听到不同回答","把问题写长，显得更加正式","按年龄设计表达，并听取孩子意愿"],"answer":3,"explanation":"孩子不是缩小版的成年人。提问方式要适合他们的理解与表达，也要认真听取愿意或不愿意参与的声音。一份儿童研究清单把这些内容列为重点；它由专家共同制定，后续仍需要儿童和家庭参与完善。","bridge":"换一种孩子听得懂的问法，就走进了儿童研究设计的问题。","paperId":"nursing-39615432","tryThis":"用30秒把“请评价本产品的可用性”改成一句小朋友也容易理解的问题。","keywords":["儿童参与","问卷设计","研究方法"],"paper":{"id":"nursing-39615432","title":"A child-centred research checklist to improve the design and reporting of paediatric research studies: A descriptive mixed methods study.","venue":"International Journal of Nursing Studies","year":2025,"url":"https://doi.org/10.1016/j.ijnurstu.2024.104958","doi":"10.1016/j.ijnurstu.2024.104958","summary":["研究儿童时，怎样才能把孩子的意愿和表达方式放在中心，而不是只听成人的意见？","研究先梳理文献并征求国际专家意见，再用三轮德尔菲咨询逐步形成研究设计与报告清单。","清单强调同意或拒绝、研究行为规范和适合儿童的方法，共有11条陈述；后续仍需要儿童和家庭参与完善。"],"methods":["混合方法研究","德尔菲专家咨询"]}}];